function renderICD(){
 const chapters=[['I','A00–B99','Некоторые инфекционные и паразитарные болезни','A00-B99'],['II','C00–D48','Новообразования','C00-D48'],['III','D50–D89','Болезни крови и отдельные нарушения иммунитета','D50-D89'],['IV','E00–E90','Болезни эндокринной системы и обмена веществ','E00-E90'],['V','F00–F99','Психические расстройства и расстройства поведения','F00-F99'],['VI','G00–G99','Болезни нервной системы','G00-G99'],['VII','H00–H59','Болезни глаза и его придаточного аппарата','H00-H59'],['VIII','H60–H95','Болезни уха и сосцевидного отростка','H60-H95'],['IX','I00–I99','Болезни системы кровообращения','I00-I99'],['X','J00–J99','Болезни органов дыхания','J00-J99'],['XI','K00–K93','Болезни органов пищеварения','K00-K93'],['XII','L00–L99','Болезни кожи и подкожной клетчатки','L00-L99'],['XIII','M00–M99','Болезни костно-мышечной системы и соединительной ткани','M00-M99'],['XIV','N00–N99','Болезни мочеполовой системы','N00-N99'],['XV','O00–O99','Беременность, роды и послеродовой период','O00-O99'],['XVI','P00–P96','Отдельные состояния перинатального периода','P00-P96'],['XVII','Q00–Q99','Врождённые аномалии, деформации и хромосомные нарушения','Q00-Q99'],['XVIII','R00–R99','Симптомы, признаки и отклонения от нормы','R00-R99'],['XIX','S00–T98','Травмы, отравления и другие последствия воздействия внешних причин','S00-T98'],['XX','U00–U85','Коды для специальных целей','U00-U85'],['XXI','V01–Y98','Внешние причины заболеваемости и смертности','V01-Y98'],['XXII','Z00–Z99','Факторы, влияющие на состояние здоровья и обращения за медицинской помощью','Z00-Z99']];
 return '<div class="page-heading"><div><div class="eyebrow">ПОИСКОВЫЙ КАТАЛОГ</div><h1>Международная классификация болезней · 10-й пересмотр</h1><p class="lead">Полный российский классификатор Минздрава: поиск работает прямо на сайте, без стороннего API.</p></div><span class="date-chip">Версия 2.27 · 15 038 записей</span></div>'+
 '<section class="card card-pad icd-search-card"><label class="icd-search-label" for="icd-query">Что ищем?</label><div class="icd-search-row"><span class="icd-search-icon">'+icon('search',20)+'</span><input id="icd-query" type="search" autocomplete="off" placeholder="Например, G43.1 или мигрень" aria-describedby="icd-search-help"><button id="icd-clear" class="button button-outline" type="button">Очистить</button></div><p id="icd-search-help" class="source-citation">Поиск по всем кодам и названиям. Результаты можно раскрыть полностью, включая неактуальные записи.</p><div class="icd-filter-row"><label><input id="icd-include-inactive" type="checkbox"> Показывать неактуальные записи</label><span id="icd-count-label">15 038 записей в базе</span></div><div id="icd-status" class="icd-status" role="status" aria-live="polite">Начни вводить запрос — поиск по локальной базе уже готов.</div><div id="icd-results" class="icd-results"></div><div id="icd-more-wrap" class="icd-more-wrap"></div></section>'+
 '<section class="icd-chapters-section"><div class="section-head"><div><div class="eyebrow">СТРУКТУРА КЛАССИФИКАЦИИ</div><h2>Классы МКБ-10</h2></div><span class="soft-chip">22 класса</span></div><div class="icd-chapters-grid">'+chapters.map(c=>'<button class="icd-chapter" type="button" data-icd-chapter="'+c[3]+'"><span class="icd-chapter-number">'+c[0]+'</span><span class="icd-chapter-copy"><strong>'+esc(c[2])+'</strong><small>'+c[1]+'</small></span>'+icon('arrow',15)+'</button>').join('')+'</div></section>'+
 '<section class="icd-source-note"><strong>Источник и версия данных</strong><p>Российская МКБ-10, версия 2.27 от 02.09.2024 · OID 1.2.643.5.1.13.13.11.1005. В локальной базе сохранены все 15 038 записей, иерархия, признаки актуальности, дополнительные коды и даты изменений. Поиск не зависит от внешнего API.</p><a href="https://nsi.rosminzdrav.ru/dictionaries/1.2.643.5.1.13.13.11.1005/passport/2.27" target="_blank" rel="noopener noreferrer">Паспорт справочника Минздрава '+icon('external',13)+'</a></section>';
}
function bindICD(){
 const input=document.getElementById('icd-query'),status=document.getElementById('icd-status'),results=document.getElementById('icd-results'),clear=document.getElementById('icd-clear'),includeInactive=document.getElementById('icd-include-inactive'),moreWrap=document.getElementById('icd-more-wrap'),countLabel=document.getElementById('icd-count-label');
 const DATA_URL=new URL('../data/icd10-v2.27.json',import.meta.url).href,PAGE_SIZE=100;
 let timer=null,allRecords=[],byId=new Map(),lastMatches=[],visibleCount=PAGE_SIZE,chapterRange='',dataPromise=null;
 const normalize=v=>String(v??'').normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').match(/[\p{L}\p{N}]+/gu)?.join(' ')||'';
 const normalizeCode=v=>String(v??'').toUpperCase().replace(/[^A-ZА-Я0-9.]/g,'');
 async function loadData(){
  if(allRecords.length)return allRecords;
  if(dataPromise)return dataPromise;
  status.textContent='Загружаем локальную базу МКБ-10…';
  dataPromise=(async()=>{
   const response=await fetch(DATA_URL,{cache:'no-cache'});
   if(!response.ok)throw new Error('Не удалось загрузить локальную базу: HTTP '+response.status+' ('+DATA_URL+')');
   const payload=await response.json();
   if(payload.version!=='2.27'||payload.records?.length!==15038)throw new Error('Контроль целостности базы не пройден: ожидалось 15 038 записей версии 2.27.');
   allRecords=payload.records.map(r=>({id:r[0],recCode:r[1],code:r[2],name:r[3],parentId:r[4],addlCode:r[5],actual:r[6],date:r[7]}));
   byId=new Map(allRecords.map(x=>[x.id,x]));
   countLabel.textContent=allRecords.length.toLocaleString('ru-RU')+' записей в базе';
   status.textContent='База загружена: '+allRecords.length.toLocaleString('ru-RU')+' записей. Введи хотя бы одну букву или код.';
   return allRecords;
  })();
  try{return await dataPromise;}catch(error){dataPromise=null;throw error;}
 }
 function score(item,nq,cq){const code=normalizeCode(item.code),name=normalize(item.name);if(cq&&code===cq)return 0;if(cq&&code.startsWith(cq))return 1;if(cq&&code.includes(cq))return 2;if(name===nq)return 3;if(name.startsWith(nq))return 4;const i=name.indexOf(nq);return i>=0?5+i/1000:99;}
 function renderResults(){const q=input.value.trim(),nq=normalize(q),cq=normalizeCode(q),visible=lastMatches.slice(0,visibleCount);if(!q&&!chapterRange){results.innerHTML='';moreWrap.innerHTML='';status.textContent='Начни вводить запрос или выбери класс ниже.';return;}if(!lastMatches.length){results.innerHTML='<div class="icd-empty"><strong>Совпадений не найдено</strong><span>Попробуй другой код или формулировку.</span></div>';moreWrap.innerHTML='';status.textContent='Ничего не найдено.';return;}status.textContent='Найдено: '+lastMatches.length.toLocaleString('ru-RU')+'. Показано: '+visible.length.toLocaleString('ru-RU')+'.';results.innerHTML=visible.map(item=>{const parent=byId.get(item.parentId),addl=item.addlCode==='1'?'<span class="icd-addl-tag">Доп. код +</span>':item.addlCode==='2'?'<span class="icd-addl-tag">Доп. код *</span>':'',old=item.actual==='0'?'<span class="icd-old-tag">Неактуальная запись</span>':'';return '<article class="icd-result"><div class="icd-result-code">'+esc(item.code||'—')+'</div><div class="icd-result-main"><strong>'+esc(item.name||'Без названия')+'</strong><small>'+(parent?'Раздел: '+esc(parent.name):'Классификатор МКБ-10')+(item.date?' · дата изменения: '+esc(item.date):'')+'</small></div><div class="icd-result-tags">'+addl+old+'</div></article>';}).join('');moreWrap.innerHTML=visibleCount<lastMatches.length?'<button class="button button-outline icd-more-button" id="icd-more" type="button">Показать ещё '+Math.min(PAGE_SIZE,lastMatches.length-visibleCount)+' · осталось '+(lastMatches.length-visibleCount).toLocaleString('ru-RU')+'</button>':'';const more=document.getElementById('icd-more');if(more)more.addEventListener('click',()=>{visibleCount+=PAGE_SIZE;renderResults();});}
 async function search(){const query=input.value.trim();chapterRange='';if(!query){lastMatches=[];renderResults();return;}try{await loadData();const nq=normalize(query),cq=normalizeCode(query),includeOld=includeInactive.checked;const tokens=nq.split(' ').filter(Boolean);lastMatches=allRecords.filter(x=>{if(!includeOld&&x.actual==='0')return false;const name=normalize(x.name),rec=normalize(x.recCode),code=normalizeCode(x.code);return (tokens.length>0&&tokens.every(token=>name.includes(token)||rec.includes(token)))||(!!cq&&code.includes(cq));});lastMatches.sort((a,b)=>score(a,nq,cq)-score(b,nq,cq)||a.code.localeCompare(b.code,'en',{numeric:true}));visibleCount=PAGE_SIZE;renderResults();}catch(error){results.innerHTML='<div class="icd-api-fallback"><strong>Не удалось загрузить локальный справочник.</strong><p>'+esc(error.message)+'</p><a href="https://nsi.rosminzdrav.ru/dictionaries/1.2.643.5.1.13.13.11.1005/passport/2.27" target="_blank" rel="noopener noreferrer">Открыть официальный паспорт '+icon('external',13)+'</a></div>';status.textContent='Ошибка загрузки данных. Проверь подключение и обнови страницу.';}}
 function runChapter(range){chapterRange=range;input.value=range.split('-')[0];loadData().then(()=>{const [start,end]=range.split('-'),includeOld=includeInactive.checked;lastMatches=allRecords.filter(x=>{const key=normalizeCode(x.code).replace('.','').slice(0,3);return(includeOld||x.actual!=='0')&&key>=start&&key<=end;});lastMatches.sort((a,b)=>a.code.localeCompare(b.code,'en',{numeric:true}));visibleCount=PAGE_SIZE;renderResults();document.querySelector('.icd-search-card').scrollIntoView({behavior:'smooth',block:'start'});}).catch(e=>{status.textContent=e.message;});}
 input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(search,180);});clear.addEventListener('click',()=>{input.value='';chapterRange='';lastMatches=[];renderResults();input.focus();});includeInactive.addEventListener('change',()=>{if(chapterRange)runChapter(chapterRange);else if(input.value.trim())search();});document.querySelectorAll('[data-icd-chapter]').forEach(b=>b.addEventListener('click',()=>runChapter(b.dataset.icdChapter)));
 loadData().catch(error=>{status.textContent='Ошибка загрузки базы: '+error.message;results.innerHTML='<div class="icd-api-fallback"><strong>База не загрузилась.</strong><p>'+esc(error.message)+'</p><button class="button button-outline" id="icd-retry" type="button">Повторить загрузку</button></div>';document.getElementById('icd-retry')?.addEventListener('click',()=>{dataPromise=null;loadData().catch(e=>{status.textContent=e.message;});});});
}

const CLINICAL_LIBRARY=[
 {id:'headache',title:'Головная боль: первичная оценка и красные флаги',category:'Симптомы',tags:['головная боль','цефалгия','мигрень','субарахноидальное кровоизлияние','красные флаги'],updated:'Клинический обзор · РФ',summary:'Сначала исключить вторичные причины, затем описывать фенотип головной боли и его динамику.',sections:[
  {title:'Красные флаги и основания для срочной оценки',items:['Внезапное начало с достижением максимальной интенсивности в течение 5 минут.','Лихорадка с нарастающей головной болью.','Новый очаговый неврологический дефицит, когнитивное нарушение, изменение личности или снижение уровня сознания.','Недавняя травма головы (обычно в пределах последних 3 месяцев).','Связь с кашлем, натуживанием, чиханием или физической нагрузкой; выраженная позиционная зависимость.','Существенное изменение привычного характера головной боли.','Симптомы, позволяющие подозревать гигантоклеточный артериит или острый приступ закрытоугольной глаукомы.','Новая головная боль на фоне иммунодефицита/иммуносупрессии, онкологического анамнеза или необъяснимой рвоты требует рассмотрения дополнительного обследования/направления.']},
  {title:'Что уточнить в анамнезе',items:['Время начала и скорость нарастания; впервые ли возникла такая боль.','Частота, длительность, интенсивность и динамика приступов.','Локализация, характер, провоцирующие факторы и влияние повседневной активности.','Сопутствующие симптомы: тошнота, фото-/фонофобия, вегетативные проявления, зрительные/чувствительные/речевые симптомы.','Лекарства, включая частоту приёма анальгетиков; возможная связь с менструальным циклом.']},
  {title:'Ориентиры для фенотипирования',items:['Мигрень: приступообразная головная боль с характерными сопутствующими симптомами и ограничением активности; уточняй наличие и временной профиль ауры.','Головная боль напряжения: обычно двусторонняя давящая/сжимающая боль без выраженного усиления при обычной активности.','Кластерная головная боль: строго выраженные односторонние приступы с ипсилатеральными краниальными вегетативными симптомами и/или двигательным беспокойством.','Фенотип не отменяет поиск вторичной причины при красных флагах. Для классификации используй актуальные диагностические критерии, а не только эти краткие ориентиры.']},
  {title:'Диагностические ловушки',items:['Не считать внезапную «самую сильную в жизни» боль обычной мигренью без оценки опасных вторичных причин.','Не трактовать новый очаговый дефицит как ауру по умолчанию.','Не забывать о лекарственно-индуцированной/абузусной головной боли при частом приёме симптоматических препаратов.','Нормальный неврологический осмотр сам по себе не отменяет оценку анамнеза и красных флагов.']}
 ],sources:[]},
 {id:'dizziness',title:'Острое головокружение и вертиго',category:'Симптомы',tags:['головокружение','вертиго','вестибулярный синдром','оценка глазодвигательных реакций','ДППГ','инсульт'],updated:'Клинический обзор · РФ',summary:'Классифицируй эпизод по времени и триггерам, а не только по слову «головокружение».',sections:[
  {title:'Сначала определи временной паттерн',items:['Острый вестибулярный синдром: остро возникшие непрерывные симптомы — головокружение/вертиго, тошнота или рвота, неустойчивость; оцени длительность и непрерывность.','Спонтанный эпизодический синдром: повторные эпизоды без очевидного позиционного триггера — рассматривай в том числе транзиторную ишемию, вестибулярную мигрень и болезнь Меньера.','Триггерный эпизодический синдром: короткие приступы, воспроизводимо запускаемые определённым движением/положением головы; типичный пример — ДППГ.','Уточняй, является ли движение причиной приступа или лишь усиливает уже постоянное головокружение.']},
  {title:'Признаки, требующие исключения центральной причины',items:['Внезапное головокружение с очаговым неврологическим дефицитом.','Новая выраженная неустойчивость походки, вертикальный или меняющий направление нистагм, новое снижение слуха в соответствующем остром контексте.','При подозрении на инсульт задней циркуляции — немедленная оценка по локальному инсультному маршруту.','']},
  {title:'Осмотр и специальные тесты',items:['Комплекс оценки глазодвигательных реакций применим не как универсальный тест «на любое головокружение», а только в правильном клиническом контексте: при остром вестибулярном синдроме, обычно при наличии нистагма, и специалистом с соответствующей подготовкой и опытом.','При остром вестибулярном синдроме с нистагмом обученный специалист оценивает реакцию на импульсное движение головы, характер нистагма и вертикальное расхождение глаз; дополнительно оценивают слух. Центральный или сомнительный результат требует нейровизуализации по соответствующему маршруту.','При кратковременном позиционно-провоцируемом вертиго используй пробу Дикса—Холлпайка при наличии навыка; при подтверждённом заднеканальном ДППГ — репозиционный манёвр Эпли, если нет противопоказаний.','Оцени черепные нервы, поля зрения, движения глаз, координацию, походку и способность самостоятельно стоять/ходить.']},
  {title:'Чего не делать',items:['Не использовать комплекс глазодвигательных проб у пациента без подходящего синдрома или без специальной подготовки: неверное выполнение и интерпретация создают ложную уверенность.','Не считать КТ надёжным методом исключения центральной причины острого вестибулярного синдрома.','Не назначать визуализацию автоматически при типичном позиционном синдроме без атипичных признаков; решение зависит от клинической картины и локального протокола.']}
 ],sources:[]},
 {id:'weakness',title:'Слабость в конечностях: острый и прогрессирующий дефицит',category:'Синдромы',tags:['слабость','парез','гемипарез','парапарез','инсульт','синдром конского хвоста'],updated:'Клинический обзор · РФ',summary:'Важнейшие развилки — скорость развития, распределение дефицита, сопутствующие стволовые/дыхательные и тазовые симптомы.',sections:[
  {title:'Срочность по темпу развития',items:['Внезапная слабость конечности или лица, даже ограниченная одной кистью, может быть проявлением инсульта/ТИА: оцени немедленно по локальному инсультному маршруту.','Очень быстрое нарастание слабости одной конечности или гемипареза в течение часов–дней требует срочного обследования, включая нейровизуализацию, для исключения структурной причины.','Быстро прогрессирующая симметричная слабость в течение 4 недель требует немедленной неврологической оценки с оценкой бульбарной и дыхательной функции.','При медленно прогрессирующей слабости в течение недель–месяцев оцени признаки нейромышечного заболевания; дисфагия требует срочной оценки, одышка в покое или лёжа — немедленной.']},
  {title:'Локализация: что описать до диагностической гипотезы',items:['Распределение: монопарез, гемипарез, парапарез, тетрапарез; проксимальный или дистальный акцент.','Симметричность и последовательность вовлечения конечностей.','Тонус, сухожильные рефлексы, патологические стопные знаки, атрофии и фасцикуляции.','Сопутствующие чувствительные, координаторные, черепно-нервные, тазовые и дыхательные нарушения.','Функциональная тяжесть: ходьба, вставание, удержание предметов, глотание, речь, дыхание.']},
  {title:'Не пропустить компрессию конского хвоста',items:['Сильная боль в пояснице с иррадиацией в ногу в сочетании с новым нарушением мочеиспускания, дефекации или сексуальной функции либо онемением промежности требует немедленной оценки по локальному маршруту исключения синдрома конского хвоста.','Не ждать полного набора симптомов и не успокаиваться отсутствием одного отдельного признака.']},
  {title:'Диагностические ловушки',items:['Не исключать инсульт из-за небольшого объёма слабости: внезапная изолированная слабость кисти также может быть сосудистым событием.','Не объяснять прогрессирующую слабость только болью или возрастными изменениями без проверки объективного дефицита.','Не откладывать оценку дыхания и глотания при быстро прогрессирующей симметричной слабости.']}
 ],sources:[]},
 {id:'sensory',title:'Онемение и парестезии: распределение и темп',category:'Симптомы',tags:['онемение','парестезии','чувствительность','полинейропатия','радикулопатия','аура'],updated:'Клинический обзор · РФ',summary:'Распределение чувствительных нарушений, рефлексы и скорость развития помогают выбрать направление дальнейшей оценки.',sections:[
  {title:'Паттерны, меняющие срочность',items:['Внезапное преходящее одностороннее онемение оценивай по маршруту инсульта/ТИА.','Быстро прогрессирующие в течение часов–дней симметричные онемение и слабость либо нарушение равновесия требуют немедленной неврологической оценки.','Краткие (менее 2 минут), повторяющиеся и стереотипные чувствительные эпизоды — повод оценить вероятность эпилептических приступов.','Полностью обратимые чувствительные симптомы, постепенно развивающиеся не менее 5 минут и продолжающиеся 5–60 минут, могут соответствовать ауре мигрени; оцени контекст и альтернативы.']},
  {title:'Распределение и рефлексы',items:['Дистальное симметричное распределение по типу «носков/перчаток» вместе со сниженными сухожильными рефлексами поддерживает гипотезу периферической полинейропатии.','','Стойкие дистальные чувствительные нарушения в сочетании с оживлёнными рефлексами требуют оценки возможного поражения головного или спинного мозга.','Дерматомное распределение с корешковой болью и изменением соответствующего рефлекса может направлять к радикулопатии, но не заменяет полноценную топическую оценку.']},
  {title:'Что документировать',items:['Модальность: боль/температура, вибрация, положение/движение, лёгкое прикосновение.','Точная граница нарушения, сторона, симметрия и распространение во времени.','Есть ли слабость, атаксия, изменение походки, тазовые симптомы или боль в позвоночнике.','Сопоставляй чувствительный уровень, рефлексы и двигательную функцию; отдельно фиксируй субъективные ощущения и объективные находки.']},
  {title:'Диагностические ловушки',items:['Не сводить любое онемение к «остеохондрозу» без локализации и проверки центральных признаков.','Не считать нормальную силу достаточной для исключения значимой центральной патологии при внезапном одностороннем симптоме.','Не назначать лабораторную панель механически: интерпретируй тесты с учётом анамнеза, осмотра и предтестовой вероятности.']}
 ],sources:[]}

,
 {id:'stroke',title:'Острый инсульт: распознавание и первичный маршрут',category:'Неотложные состояния',tags:['инсульт','ОНМК','оценка лица рук и речи','гемипарез','афазия','задняя циркуляция','тромбэктомия','тромболизис'],updated:'Клинический обзор · РФ',summary:'Внезапный очаговый дефицит — сосудистое событие, пока не доказано обратное. Время начала и немедленная маршрутизация критически важны.',sections:[
  {title:'Распознавание и время',items:['Фиксируй точное время начала симптомов и отдельно — время, когда пациента в последний раз достоверно видели без симптомов. При пробуждении с симптомами это не обязательно время обнаружения.','Быстрая проверка симметрии лица, движений рук и речи помогает распознать инсульт, но нормальный результат такой проверки не исключает инсульт: возможны изолированные нарушения зрения, равновесия, координации, чувствительности или другие заднециркуляторные проявления.','Уточни внезапность, динамику, флюктуации, регресс, исходный функциональный статус и наличие похожих эпизодов.','Проверь глюкозу крови как потенциальную имитацию инсульта, не задерживая экстренную оценку.']},
  {title:'Первичная оценка',items:['Активируй локальный инсультный маршрут без промедления; не жди полного набора симптомов или результатов плановых анализов.','Оцени дыхательные пути, дыхание, кровообращение, уровень сознания, глюкозу, АД, температуру и сатурацию в соответствии с локальным протоколом.','Зафиксируй очаговый дефицит структурированно: речь, взгляд, поля зрения, лицо, сила и чувствительность конечностей, координация, игнорирование, походка если безопасно.','Уточни антикоагулянты/антиагреганты, время последней дозы, недавние операции/кровотечения, судороги при дебюте, травму и коморбидность.']},
  {title:'Нейровизуализация и дифференциальный ряд',items:['Нативная КТ быстро выявляет внутричерепное кровоизлияние и ряд альтернативных причин; при подозрении на окклюзию крупного сосуда маршрут может включать КТ-ангиографию и перфузионную визуализацию.','Нормальная ранняя КТ не исключает ишемический инсульт, особенно небольшое или заднециркуляторное поражение.','Дифференциальный ряд включает гипогликемию, постиктальный парез, мигренозную ауру, функциональное неврологическое расстройство, опухоль/субдуральную гематому и метаболические нарушения.','Решение о реперфузионном лечении принимает инсультная команда по актуальным критериям и визуализации; справочник не заменяет протокол и не рассчитывает пригодность к лечению.']},
  {title:'Диагностические ловушки',items:['Не исключай инсульт из-за низкого балла шкалы или небольшого дефицита: клиническая значимость зависит от функции, которую симптом нарушает.','Не путай время обнаружения симптомов с последним временем, когда пациента достоверно видели без симптомов.','Не считай регресс симптомов доказательством отсутствия сосудистого события: это может быть ТИА или инсульт с ранним улучшением.','Не задерживай направление ради сбора полного анамнеза или попытки самостоятельно завершить диагностику.']}
 ],sources:[]},
 {id:'tia',title:'Транзиторная ишемическая атака (ТИА)',category:'Неотложные состояния',tags:['ТИА','транзиторная ишемическая атака','преходящая слабость','амавроз','оценка риска инсульта после ТИА','инсульт'],updated:'Клинический обзор · РФ',summary:'Исчезновение очаговых симптомов не снимает срочности: предполагаемая ТИА требует немедленного специализированного маршрута.',sections:[
  {title:'Клинический паттерн',items:['Подозревай ТИА при внезапном очаговом неврологическом симптоме с полным регрессом: односторонняя слабость/онемение, нарушение речи, монокулярная потеря зрения или другие соответствующие очаговые проявления.','Уточни точное время начала, продолжительность, последовательность симптомов и момент полного восстановления.','Попроси очевидцев описать событие; различай отрицательные симптомы (потеря функции) и позитивные феномены (мерцание, покалывание, подёргивания), но не используй один признак изолированно для исключения ишемии.','Проверь альтернативы: мигренозная аура, фокальный приступ, гипогликемия, синкопе и периферическая патология.']},
  {title:'Срочность и обследование',items:['','Не откладывай направление ради планового обследования или самостоятельного подсчёта прогностических баллов.','','Визуализация выбирается специалистом: КТ не назначается рутинно только из-за подозрения на ТИА; МРТ с диффузионными и чувствительными к крови последовательностями может уточнять ишемию, кровоизлияние и альтернативы.']},
  {title:'Что важно выяснить',items:['Сосудистые факторы риска: АГ, диабет, дислипидемия, курение, фибрилляция предсердий, сосудистые заболевания.','Лекарства: антикоагулянты, антиагреганты, гипотензивные препараты; приверженность и недавние изменения.','Предыдущие ТИА/инсульт, сосудистые вмешательства, кровотечения и противопоказания к терапии.','Характер зрительного нарушения: монокулярное или бинокулярное, негативное или позитивное, внезапное или постепенно распространяющееся.']},
  {title:'Ловушки',items:['«Уже прошло» — не аргумент для планового наблюдения.','Не считать шкалу оценки риска инсульта после ТИА диагностическим тестом и не использовать её вместо срочной клинической оценки.','Не называть ТИА любое преходящее головокружение или неспецифическое онемение без клинической локализации.']}
 ],sources:[]},
 {id:'seizure',title:'Первый эпилептический приступ и диагностика эпилепсии',category:'Синдромы',tags:['эпилепсия','судороги','первый приступ','ЭЭГ','МРТ','потеря сознания',''],updated:'Клинический обзор · РФ',summary:'Сначала реконструируй событие и исключи имитаторы. ЭЭГ поддерживает диагноз, но нормальная ЭЭГ эпилепсию не исключает.',sections:[
  {title:'Реконструкция эпизода',items:['Получай описание пациента и очевидца; по возможности изучай безопасно полученную видеозапись эпизода.','Уточни обстоятельства начала, предупреждающие ощущения, последовательность моторных и немоторных проявлений, реакцию на обращение, память о событии и восстановление.','Отдельно фиксируй длительность, повторяемость, стереотипность, травмы, прикус языка, недержание, постиктальную спутанность и мышечную болезненность.','Уточни сон, лихорадку, инфекции, алкоголь/отмену веществ, новые лекарства, пропуски противосудорожной терапии и возможные метаболические провокаторы.']},
  {title:'Имитаторы и первичная проверка',items:['','Проверь глюкозу и оцени метаболические/токсические причины с учётом клинического контекста.','Дифференциальный ряд включает синкопе, психогенные неэпилептические приступы, парасомнии, мигрень, транзиторные ишемические симптомы и двигательные расстройства.','Не делай вывод по одному признаку (например, прикусу языка или недержанию): важна совокупность анамнеза и осмотра.']},
  {title:'ЭЭГ и нейровизуализация',items:['При клиническом подозрении на эпилептический приступ ЭЭГ может поддержать диагноз и помочь классифицировать приступ/синдром; не используй нормальную ЭЭГ для исключения эпилепсии.','','','Срочная нейровизуализация рассматривается при подозрении на структурную причину или острое поражение; выбор метода зависит от ситуации.']},
  {title:'Классификация приступов',items:['','В новой классификации «сознание» учитывает и осознанность, и реактивность; описание должно отражать хронологическую последовательность признаков, а не только первый замеченный симптом.','Отделяй тип приступа от типа эпилепсии и эпилептического синдрома; эти уровни классификации отвечают на разные вопросы.','При неясном событии фиксируй неопределённость, не присваивая тип приступа по догадке.']},
  {title:'После первого приступа',items:['','Обсуди индивидуальный риск повторения, безопасность, вождение и местные юридические ограничения; они различаются по странам.','Не приравнивай один неспровоцированный приступ автоматически к эпилепсии: диагноз требует применения действующих критериев и оценки риска рецидива.']}
 ],sources:[]},
 {id:'status',title:'Эпилептический статус и серийные приступы',category:'Неотложные состояния',tags:['эпилептический статус','судорожный статус','5 минут','серийные приступы','кластер','бессудорожный статус'],updated:'Клинический обзор · РФ',summary:'Продолжающийся судорожный приступ 5 минут и более — неотложное состояние. Действуй по экстренному протоколу, не жди самопроизвольного прекращения.',sections:[
  {title:'Когда считать неотложным',items:['','Повторные/кластерные приступы (обычно 3 и более самопрекращающихся приступа за 24 часа) рассматриваются как медицинская неотложная ситуация.','Продолжительный приступ, длящийся более чем на 2 минуты дольше обычной длительности приступа конкретного пациента, также требует экстренного плана.','Не забывай о бессудорожном статусе: длительное или флюктуирующее нарушение сознания после приступа требует срочной оценки, включая ЭЭГ по доступности и клинической ситуации.']},
  {title:'Параллельные действия',items:['Немедленно активируй локальный протокол неотложной помощи и обеспечь оценку проходимости дыхательных путей, дыхания и кровообращения, мониторинг, доступ к реанимационным ресурсам и защиту от травмы.','Зафиксируй время начала и продолжительность, число приступов, восстановление сознания между ними и ранее принятые препараты.','Проверь потенциально обратимые причины, включая гипогликемию, нарушения электролитов, инфекцию, интоксикацию/отмену алкоголя, эклампсию и пропуски противосудорожных препаратов.','Если есть индивидуальный план экстренного лечения, он имеет приоритет при условии доступности и соответствия текущей ситуации.']},
  {title:'Лечение и эскалация',items:['Медикаментозное купирование проводится обученной командой по действующему локальному протоколу с учётом дыхательных рисков, противопоказаний и доступного мониторинга.','','','Не допускай задержки лечения из-за ожидания ЭЭГ или полного набора лабораторных результатов.']},
  {title:'Ловушки',items:['Не путай постиктальную спутанность с продолжающимся бессудорожным статусом без оценки динамики и контекста.','Не считай прекращение видимых судорог гарантией восстановления сознания.','Не вводи лекарственные схемы из справочника вместо протокола дозирования и мониторинга.']}
 ],sources:[]},
 {id:'parkinson',title:'Паркинсонизм и болезнь Паркинсона',category:'Заболевания',tags:['болезнь Паркинсона','паркинсонизм','брадикинезия','ригидность','тремор покоя','постуральная неустойчивость'],updated:'Клинический обзор · РФ',summary:'Ключевой шаг — подтвердить синдром паркинсонизма, затем оценить фенотип и признаки, указывающие на альтернативный диагноз.',sections:[
  {title:'Клиническое распознавание',items:['Брадикинезия — центральный клинический элемент паркинсонизма; оценивай замедление и уменьшение амплитуды повторных движений, а не только общую медлительность.','Ищи ригидность и тремор покоя; постуральная неустойчивость может появляться позднее и имеет широкий дифференциальный ряд.','Оцени асимметрию, походку, повороты, уменьшение размаха рук, мимику, речь, почерк и бытовую функцию.','Собери сведения о немоторных проявлениях: гипосмия, запоры, нарушения сна с двигательным поведением, ортостатические симптомы, настроение и когнитивные изменения.']},
  {title:'Дифференциальная диагностика',items:['Проверь лекарственные причины (например, блокаторы дофаминовых рецепторов), сосудистый паркинсонизм и другие вторичные причины.','Ранние частые падения, выраженная ранняя вегетативная недостаточность, пирамидные/мозжечковые признаки, вертикальный надъядерный парез взора или раннее тяжёлое когнитивное нарушение заставляют пересмотреть типичный диагноз.','Существенная симметрия с самого начала и быстрое прогрессирование могут быть нетипичными, но ни один признак сам по себе не устанавливает альтернативный диагноз.','']},
  {title:'Подтверждение и наблюдение',items:['','Диагноз клинический и должен регулярно пересматриваться; при появлении атипичных признаков диагностическую гипотезу нужно переоценить.','Структурируй описание моторного фенотипа и функционального влияния; шкалы тяжести не заменяют клинический осмотр.','Учитывай лекарственные колебания, дискинезии, падения, глотание, речь, сон, настроение, когнитивный статус и автономные симптомы при последующих оценках.']},
  {title:'Ловушки',items:['Изолированный тремор не равен болезни Паркинсона.','Ответ на леводопу может поддерживать гипотезу, но не должен быть единственным диагностическим критерием.','Не списывай ранние падения, бульбарные симптомы или выраженную вегетативную недостаточность на «обычное течение» без пересмотра диагноза.']}
 ],sources:[]},
 {id:'ms',title:'Рассеянный склероз: клинический эпизод, диагностика и обострение',category:'Заболевания',tags:['рассеянный склероз','РС','демиелинизация','оптический неврит','симптом Лермитта','диагностические критерии рассеянного склероза'],updated:'Клинический обзор · РФ',summary:'Подозрение строится на объективном очаговом неврологическом эпизоде и доказательствах диссеминации; неспецифические симптомы сами по себе недостаточны.',sections:[
  {title:'Типичные клинические проявления',items:['Возможны болезненное снижение зрения на один глаз, диплопия, восходящие чувствительные нарушения/слабость, симптом Лермитта, нарушение равновесия и походки.','Типичный эпизод развивается более 24 часов, сохраняется дни или недели и может частично регрессировать; лихорадка и инфекция требуют поиска альтернативы или псевдообострения.','Уточняй предыдущие эпизоды, разделённые временем и анатомической локализацией, даже если они полностью регрессировали.','Усталость, депрессия, головокружение или расплывчатые парестезии без очаговых симптомов/признаков сами по себе не являются достаточным основанием подозревать РС.']},
  {title:'Диагностический подход',items:['До направления подтвердить, что эпизод действительно неврологический: анамнез, объективный осмотр и исключение более частых альтернатив.','','МРТ оценивается с учётом типичной локализации и характера очагов, диссеминации во времени/пространстве и возможных альтернатив. Само наличие неспецифических очагов на МРТ не доказывает РС.','При изолированном оптическом неврите требуется профильная офтальмологическая и неврологическая оценка; отдельно учитывай заболевание спектра оптиконейромиелита и заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину в соответствующем фенотипе.']},
  {title:'Обострение или псевдообострение',items:['','Перед тем как назвать состояние обострением, исключи инфекцию — особенно мочевую и респираторную — и отличи истинный рецидив от колебаний симптомов или прогрессирования.','Не каждое обострение требует стероидной терапии; решение зависит от влияния на функцию, тяжести и оценки специалиста.','Фиксируй дату начала, объективные изменения, функциональное влияние, восстановление и возможные провоцирующие факторы.']},
  {title:'Ловушки',items:['Не диагностируй РС по одному неспецифическому симптому или случайным очагам на МРТ.','Не называй ухудшение на фоне лихорадки/инфекции новым обострением, пока не оценена псевдоактивация старых симптомов.','Не применяй диагностические критерии рассеянного склероза механически вне подходящего клинического контекста и без исключения альтернатив.']}
 ],sources:[]},
 {id:'delirium',title:'Делирий и острое изменение психического статуса',category:'Синдромы',tags:['делирий','спутанность сознания','острое когнитивное нарушение','четырёхфакторный тест оценки делирия','гипоактивный делирий'],updated:'Клинический обзор · РФ',summary:'Острое или флюктуирующее изменение внимания и когнитивных функций — повод искать соматическую причину, а не сразу объяснять всё деменцией.',sections:[
  {title:'Клинический паттерн',items:['Ключевой признак — новое изменение за часы или дни, часто с колебаниями в течение суток.','Оцени внимание, скорость ответов, ориентировку, восприятие, сон, психомоторную активность, коммуникацию и функциональный уровень.','Делирий может быть гиперактивным, гипоактивным или смешанным; тихий, заторможенный пациент не менее важен, чем возбуждённый.','Обязательно выясни исходный когнитивный статус у родственников/ухаживающих и сравни с текущим состоянием.']},
  {title:'Поиск причин и оценка',items:['Ищи сочетание причин: инфекция, гипоксия, обезвоживание, боль, метаболические нарушения, задержка мочи/запор, лекарственные эффекты или отмена веществ.','Проверь лекарства и недавние изменения, особенно препараты с антихолинергической нагрузкой, седативные средства и полипрагмазию.','','Неврологический очаговый дефицит, травма, судорожный статус, менингеальные признаки или быстрое необъяснимое ухудшение требуют отдельной срочной оценки.']},
  {title:'Отличие от деменции',items:['Делирий обычно начинается остро и флюктуирует; деменция чаще развивается постепенно. Однако делирий может возникать поверх существующей деменции.','','Нормальный краткий когнитивный тест не отменяет клиническую оценку, особенно при выраженных колебаниях и нарушении внимания.']},
  {title:'Ловушки',items:['Не пропускай гипоактивный вариант.','Не фиксируй «деменцию» без выяснения временного профиля и исходного уровня.','Не ограничивайся назначением седативного препарата: ищи и устраняй провоцирующие причины.']}
 ],sources:[]},
 {id:'dementia',title:'Когнитивное снижение и деменция: первичная оценка',category:'Синдромы',tags:['деменция','когнитивное снижение','болезнь Альцгеймера','лобно-височная деменция','деменция с тельцами Леви','быстро прогрессирующая деменция'],updated:'Клинический обзор · РФ',summary:'Оцени не только результат теста, но и изменение повседневной функции, временной профиль и сведения близких.',sections:[
  {title:'Анамнез и функциональный профиль',items:['Уточни начало и динамику: постепенное, ступенеобразное, флюктуирующее или быстрое ухудшение.','Собери анамнез у пациента и, если возможно, у человека, хорошо знающего его повседневное функционирование.','Разделяй память, исполнительные функции, речь, зрительно-пространственные навыки, поведение, внимание и социальное познание.','Оцени влияние на финансы, лекарства, приготовление пищи, ориентировку, вождение, самообслуживание и безопасность.']},
  {title:'Исключение обратимых и сопутствующих причин',items:['Рассмотри делирий, депрессию, нарушения сна, сенсорный дефицит, употребление алкоголя/веществ и лекарственную нагрузку, включая антихолинергические препараты.','','Не исключай деменцию только на основании нормального результата короткого когнитивного теста.','Если подозрение сохраняется после оценки обратимых причин, направь в специализированную службу диагностики деменции.']},
  {title:'Подтип и дальнейшие исследования',items:['При специализированной оценке сопоставляют неврологический осмотр, профиль когнитивного дефицита, функциональные изменения и данные информанта.','Структурная визуализация обычно помогает исключить обратимые причины и уточнить подтип, если диагноз не очевиден.','При подозрении на быстро прогрессирующую деменцию требуется неврологическая оценка с доступом к специализированным исследованиям, включая ликвор при соответствующих показаниях.','Подтип имеет значение: профиль памяти, зрительно-пространственные нарушения, флюктуации, зрительные галлюцинации, паркинсонизм, поведенческие/языковые изменения могут направлять дальнейшую диагностику.']},
  {title:'Ловушки',items:['Не ставь диагноз по одному результату кратких когнитивных шкал без анамнеза и оценки повседневного функционирования.','Не считай возраст или низкий уровень образования самостоятельным объяснением прогрессирующего снижения.','Не пропускай делирий поверх деменции и быстро прогрессирующие состояния.']}
 ],sources:[]},
 {id:'neuropathic-pain',title:'Нейропатическая боль: фенотипирование и подход к оценке',category:'Синдромы',tags:['нейропатическая боль','аллодиния','гипералгезия','жжение','прострелы','сенситизация'],updated:'Клинический обзор · РФ',summary:'Нейропатическую боль следует связывать с поражением или заболеванием соматосенсорной системы и подтверждать согласованностью анамнеза, распределения и осмотра.',sections:[
  {title:'Характеристика боли',items:['Уточни качество: жжение, электрические прострелы, болезненный холод, покалывание, онемение, болезненность от лёгкого прикосновения.','Зафиксируй локализацию, распространение, симметрию, временной профиль, триггеры и связь с движением/положением.','Ищи негативные сенсорные признаки (снижение чувствительности) и позитивные (аллодиния, гипералгезия, дизестезии).','Оцени сон, настроение, повседневную функцию, мобильность и влияние боли на участие в обычной жизни.']},
  {title:'Неврологическая локализация',items:['Сопоставь распределение с периферическим нервом, корешком, длино-зависимой полинейропатией, спинным мозгом или центральным поражением.','Проверь модальности чувствительности, рефлексы, силу, координацию и походку; документируй объективные находки отдельно от субъективной боли.','Рассмотри причины: диабетическая/метаболическая полинейропатия, дефицит B12, компрессия нерва/корешка, постгерпетическая невралгия, травма, центральное поражение.','Внезапный дефицит, прогрессирующая слабость, тазовые симптомы, системные признаки или онкологический анамнез требуют оценки на опасную причину, а не только лечения боли.']},
  {title:'',items:['','Выбор зависит от сопутствующих заболеваний, взаимодействий, риска нежелательных эффектов, беременности, функции почек, предпочтений пациента и локальных правил назначения.','После начала или изменения лечения проводи раннюю оценку титрации, переносимости и нежелательных явлений; далее регулярно оценивай контроль боли, сон, функцию и необходимость продолжения.','При тяжёлой боли, существенном ограничении повседневной активности или ухудшении основного заболевания рассматривай направление в профильную службу боли/по заболеванию.']},
  {title:'Ловушки',items:['Не приравнивай любую хроническую боль к нейропатической.','Не назначай препарат только по названию симптома без оценки механизма и противопоказаний.','Не забывай о постепенной отмене некоторых препаратов и риске симптомов отмены; следуй актуальной инструкции и локальным правилам.']}
 ],sources:[]},
 {id:'trigeminal-neuralgia',title:'Невралгия тройничного нерва и лицевая боль',category:'Синдромы',tags:['невралгия тройничного нерва','лицевая боль','тригеминальная невралгия','триггерные зоны','карбамазепин'],updated:'Клинический обзор · РФ',summary:'Короткие повторные электрические лицевые пароксизмы с триггерами характерны для невралгии тройничного нерва; стойкий дефицит или атипичная боль требуют расширения поиска.',sections:[
  {title:'Фенотип боли',items:['Классический клинический паттерн — внезапные, краткие, интенсивные, односторонние электрические/стреляющие боли в зоне одной или нескольких ветвей тройничного нерва.','Приступы могут провоцироваться лёгким прикосновением, разговором, жеванием, чисткой зубов или холодным воздухом.','Уточни длительность каждого пароксизма, частоту, рефрактерный период, локализацию по ветвям и наличие фоновой постоянной боли.','Осмотри чувствительность лица, корнеальные рефлексы по показаниям, жевательные мышцы и другие черепные нервы.']},
  {title:'Когда искать вторичную причину',items:['Молодой возраст, двусторонние симптомы, стойкое онемение/снижение чувствительности, другие черепно-нервные признаки или прогрессирующее течение требуют пересмотра диагноза.','Дифференциальный ряд включает стоматологическую патологию, постгерпетическую невралгию, болезненную тригеминальную нейропатию, кластерную и другие тригеминальные автономные цефалгии.','Решение о МРТ и дополнительных исследованиях зависит от клинической картины и подозрения на структурную/вторичную причину.']},
  {title:'Подход к лечению и направлению',items:['','','Фиксируй влияние боли на питание, гигиену полости рта, сон, настроение и повседневную функцию.']},
  {title:'Ловушки',items:['Не объясняй всякую лицевую боль невралгией тройничного нерва.','Постоянная сенсорная потеря — повод искать нейропатию или вторичную причину.','Не начинай лекарственную терапию без оценки безопасности и взаимодействий.']}
 ],sources:[]},
 {id:'mnd',title:'Болезнь двигательного нейрона (БДН / БАС): признаки и направление',category:'Заболевания',tags:['БАС','болезнь двигательного нейрона','фасцикуляции','бульбарный синдром','дыхательная недостаточность'],updated:'Клинический обзор · РФ',summary:'Прогрессирующая необъяснимая слабость может начинаться локально. Важно рано распознать сочетание двигательных, бульбарных и дыхательных признаков.',sections:[
  {title:'Возможные первые проявления',items:['Потеря ловкости, падения, спотыкания, слабость кисти или стопы, изменение походки.','Мышечная атрофия, фасцикуляции, судороги и скованность в сочетании с прогрессирующей слабостью.','Бульбарное начало: дизартрия, дисфагия, изменение голоса, слабость языка/фасцикуляции.','Дыхательные проявления: одышка при нагрузке или лёжа, утренние головные боли, дневная сонливость и неосвежающий сон.','У части пациентов возможны когнитивные или поведенческие изменения, включая фронтотемпоральный спектр.']},
  {title:'Осмотр и дифференциальная диагностика',items:['Документируй распределение и темп прогрессирования слабости, атрофии, фасцикуляции, тонус, сухожильные рефлексы и патологические знаки.','Оцени бульбарную функцию, кашель, глотание, массу тела, одышку, ортопноэ и признаки ночной гиповентиляции.','Рассмотри потенциально лечимые имитаторы: нейропатии, миелопатии, нарушения нервно-мышечной передачи, миопатии, дефицитные и метаболические состояния.','ЭНМГ и дополнительные исследования назначаются для подтверждения паттерна и исключения альтернатив; интерпретация требует профильной экспертизы.']},
  {title:'Срочность и направление',items:['','Быстро прогрессирующая симметричная слабость в течение 4 недель требует немедленной неврологической оценки и оценки бульбарной/дыхательной функции.','Нарастающая дисфагия, слабый кашель, одышка в покое/лёжа, утренние головные боли и сонливость требуют своевременной оценки дыхательной функции и профильной команды.','При дыхательном ухудшении или невозможности безопасно глотать нужна экстренная оценка по местному маршруту.']},
  {title:'Ловушки',items:['Не ставь БАС по фасцикуляциям в отдельности: важны прогрессирующая слабость, объективный осмотр и исключение альтернатив.','Не успокаивайся отсутствием выраженных дыхательных жалоб на раннем этапе.','Не задерживай направление до завершения всех исследований в неспециализированном звене.']}
 ],sources:[]},
 {id:'facial-palsy',title:'Острая слабость мимических мышц: центральное или периферическое поражение',category:'Синдромы',tags:['паралич Белла','периферический парез лица','центральный парез лица','лицевой нерв','инсульт','закрытие глаза'],updated:'Клинический обзор · РФ',summary:'Внезапная слабость лица требует сначала исключить инсульт. Периферический паттерн сам по себе не отменяет оценку других неврологических признаков.',sections:[
  {title:'Сначала срочность',items:['Внезапная асимметрия лица, особенно с нарушением речи, слабостью руки/ноги, зрительными или координаторными симптомами, требует немедленного инсультного маршрута.','Уточни время начала и динамику, сопутствующую головную боль, боль в ухе, высыпания, нарушение слуха, головокружение и другие черепно-нервные симптомы.','Не откладывай оценку на основании того, что пациент может закрыть глаз или поднять бровь: паттерн поражения интерпретируется вместе со всей клинической картиной.']},
  {title:'Осмотр лицевого нерва',items:['Оцени симметрию лба, смыкание век, носогубную складку, улыбку, оскал, надувание щёк и удержание воздуха.','Проверь другие черепные нервы, чувствительность, силу конечностей, речь, координацию и походку.','Периферический паттерн обычно затрагивает верхнюю и нижнюю половины ипсилатеральной стороны лица, включая слабость закрытия глаза; центральное поражение часто сохраняет часть лобной функции, но это не абсолютное правило.','Оцени роговицу и риск повреждения глаза при неполном смыкании век.']},
  {title:'Паралич Белла и альтернативы',items:['Типичный паралич Белла — остро возникшая односторонняя периферическая слабость лица без признаков другой причины; диагноз клинический и требует исключения альтернатив.','Рассмотри синдром Рамсея Ханта, отит/мастоидит, болезнь Лайма в соответствующем эпидемиологическом контексте, опухолевое поражение, травму и другие краниальные нейропатии.','При прогрессирующем, рецидивирующем, двустороннем течении, выраженной боли, снижении чувствительности или других неврологических признаках нужна дополнительная оценка.']},
  {title:'Документация и безопасность',items:['Фиксируй степень слабости по отдельным движениям, полноту закрытия глаза, состояние роговицы, вкус/слух и сопутствующие симптомы.','','Объясняй, что восстановление может идти постепенно в течение месяцев; при неполном восстановлении и синкинезиях требуется повторная специализированная оценка.']}
 ],sources:[]},
 {id:'radiculopathy',title:'Шейная и пояснично-крестцовая радикулопатия',category:'Синдромы',tags:['радикулопатия','ишиас','корешковая боль','дерматом','миотом','рефлексы','грыжа диска'],updated:'Клинический обзор · РФ',summary:'Корешковый синдром — клинико-анатомическая гипотеза: сопоставляй боль, чувствительность, силу и рефлексы, а не только находку на снимке.',sections:[
  {title:'Клинический паттерн',items:['Уточни иррадиирующую боль, её путь, провокацию кашлем/натуживанием/движением, онемение и субъективную слабость.','Сопоставь чувствительные нарушения с дерматомом, двигательную слабость с миотомом и изменение рефлекса с предполагаемым корешком.','При шейной радикулопатии оцени шею, плечевой пояс, руку и кисть; при пояснично-крестцовой — спину, ягодицу, ногу, стопу и походку.','Ищи признаки миелопатии: нарушение тонкой моторики кистей, спастичность, гиперрефлексию, патологические стопные знаки, нарушение походки и тазовые симптомы.']},
  {title:'Красные флаги',items:['Новая задержка/недержание мочи, нарушение дефекации или сексуальной функции, онемение промежности в сочетании с сильной поясничной/корешковой болью требуют немедленной оценки на синдром конского хвоста.','Прогрессирующий моторный дефицит, двусторонние симптомы, признаки поражения спинного мозга, лихорадка, онкологический анамнез, травма или иммунодефицит требуют ускоренного поиска опасной причины.','При подозрении на компрессию спинного мозга или конского хвоста не откладывай экстренное направление ради амбулаторного курса лечения.']},
  {title:'Исследования и интерпретация',items:['','Находки МРТ сопоставляй с клинической стороной, уровнем и симптомами: дегенеративные изменения часто встречаются и без соответствующих жалоб.','ЭНМГ может быть полезна при неясной локализации, дифференциации корешкового и периферического поражения или несоответствии клиники и визуализации; показания определяются специалистом.']},
  {title:'Ловушки',items:['Не ставь уровень поражения только по боли без моторной/сенсорной/рефлекторной корреляции.','Не считай любую грыжу диска причиной симптомов.','Не пропускай центральные признаки, маскирующиеся под «радикулопатию».']}
 ],sources:[]},
 {id:'ataxia',title:'Атаксия и нарушение координации',category:'Синдромы',tags:['атаксия','мозжечок','дисметрия','дизартрия','нистагм','инсульт задней циркуляции','походка'],updated:'Клинический обзор · РФ',summary:'Новое острое нарушение координации может быть проявлением инсульта задней циркуляции. Сначала оцени темп и безопасность, затем локализуй.',sections:[
  {title:'Темп и клинический контекст',items:['Внезапно возникшая атаксия, особенно с головокружением, диплопией, дизартрией, дисфагией, слабостью или чувствительными симптомами, требует срочного исключения инсульта задней циркуляции.','Подострое/прогрессирующее нарушение координации требует оценки лекарственных, токсических, метаболических, воспалительных, опухолевых и дегенеративных причин.','Уточни алкоголь и другие вещества, новые препараты (включая противосудорожные и седативные), инфекции, семейный анамнез и системные симптомы.']},
  {title:'Неврологический осмотр',items:['Оцени глазодвигательные функции, нистагм, саккады, речь, глотание и координацию конечностей.','Проведи пальце-носовую и пяточно-коленную пробы, оцени дисдиадохокинез и феномен промахивания; интерпретируй с учётом слабости и сенсорного дефицита.','Оцени устойчивость сидя и стоя, широкую базу, тандемную ходьбу и зависимость от зрительного контроля; не провоцируй падение.','Различай мозжечковую атаксию, сенситивную атаксию и вестибулярную неустойчивость: они могут сочетаться, но требуют разных локализационных гипотез.']},
  {title:'Локализация и дифференциальный ряд',items:['Мозжечковое поражение может давать дисметрию, интенционный тремор, дисдиадохокинез, нистагм, дизартрию и атактическую походку.','Сенситивная атаксия часто усиливается при закрывании глаз и сочетается с нарушением проприоцепции/вибрации и изменением рефлексов.','Острое вестибулярное нарушение может имитировать атаксию; оцени нистагм, слух, походку и другие стволовые признаки.','Возможные причины включают сосудистое поражение, алкоголь/токсины, лекарственные эффекты, дефицит B12/витамина E, аутоиммунные/паранеопластические процессы и наследственные заболевания.']},
  {title:'Ловушки',items:['Не списывай внезапную атаксию на «вестибулярное головокружение» без проверки центральных признаков.','Нормальная сила не исключает тяжёлое нарушение координации.','Не проводи пробы стоя без страховки при выраженной неустойчивости.']}
 ],sources:[]},
 {id:'tremor',title:'Тремор: феноменология и дифференциальная диагностика',category:'Симптомы',tags:['тремор','тремор покоя','постуральный тремор','эссенциальный тремор','паркинсонизм','лекарственный тремор'],updated:'Клинический обзор · РФ',summary:'Опиши тремор по условиям возникновения, частоте, распределению и сопутствующим признакам до выбора диагностической категории.',sections:[
  {title:'Феноменология',items:['Определи тремор покоя, постуральный, кинетический, интенционный, изометрический или специфичный для задачи.','Зафиксируй локализацию (кисти, голова, голос, ноги), симметрию, частоту, амплитуду, влияние позы и целенаправленного движения.','Оцени влияние стресса, кофеина, недосыпа, алкоголя, лекарств и тиреотоксикоза; уточни семейный анамнез.','Проверь, уменьшается ли тремор при движении, меняется ли при отвлечении/ритмической задаче и есть ли дистоническая поза.']},
  {title:'Дифференциальные ориентиры',items:['Тремор покоя с брадикинезией и ригидностью поддерживает синдром паркинсонизма, но требует клинического подтверждения.','Двусторонний акционный тремор без других неврологических признаков может соответствовать эссенциальному тремору; оцени семейность, длительность и функциональное влияние.','Мозжечковые признаки, дистония, функциональные особенности, лекарственные/метаболические причины и усиленный физиологический тремор расширяют дифференциальный ряд.','При внезапном начале тремора с другими очаговыми симптомами оцени острое структурное/сосудистое событие.']},
  {title:'Что документировать',items:['Опиши тремор в покое, при вытянутых руках, при целенаправленном движении, письме/спирали и функциональных действиях.','Отдельно укажи брадикинезию, ригидность, дистонию, атаксию, походку, глазодвигательные и пирамидные признаки.','Пересмотри лекарства и стимуляторы; лабораторные исследования назначай по клинической гипотезе, а не одинаковой панелью всем.','']},
  {title:'Ловушки',items:['Не диагностируй болезнь Паркинсона по одному тремору.','Не считай любой двусторонний тремор эссенциальным без оценки лекарств, метаболических и других причин.','Не используй реакцию на алкоголь как самостоятельный диагностический тест.']}
 ],sources:[]}


,
 {id:'syncope',title:'Обморок и транзиторная потеря сознания',category:'Синдромы',tags:['обморок','синкопе','потеря сознания','судороги','аритмия','ортостатическая гипотензия','ЭКГ'],updated:'Клинический обзор · РФ',summary:'Не всякая потеря сознания — эпилептический приступ. Свидетельское описание, обстоятельства и ЭКГ часто важнее предположения по одному симптому.',sections:[
  {title:'Реконструкция события',items:['Получай описание пациента и очевидцев: что происходило до, во время и после эпизода. Уточни позу, нагрузку, провоцирующие обстоятельства, продромальные симптомы, цвет кожи, движения, длительность и восстановление.','','Зафиксируй прикус языка (боковая поверхность или кончик), травмы, длительность подёргиваний, постэпизодическую спутанность и одностороннюю слабость.','Уточни лекарства, сердечный анамнез, семейные случаи внезапной смерти, предшествующие эпизоды и связь с физической нагрузкой.']},
  {title:'Первичная оценка и красные флаги',items:['','Срочная кардиологическая оценка нужна при патологической ЭКГ, сердечной недостаточности, обмороке во время нагрузки, семейной внезапной смерти до 40 лет/наследственной кардиопатии, необъяснимой одышке или шуме в сердце.','Оцени ортостатическое АД, если это клинически уместно; пересмотри лекарства, способные снижать давление или влиять на ритм.','Неполное восстановление сознания, серьёзная травма, продолжающаяся боль в груди/одышка или острый неврологический дефицит требуют неотложной оценки.']},
  {title:'Синкопе или эпилептический приступ',items:['Короткие судорожные движения могут встречаться и при обычном вазовагальном обмороке; сами по себе они не доказывают эпилепсию.','В пользу эпилептического события могут говорить боковой прикус языка, поворот головы, необычная поза, длительные подёргивания, амнезия наблюдавшегося поведения, спутанность после события и продромальное ощущение уже виденного или никогда не виденного.','Потливость, длительное стояние, бледность и симптомы, которые удавалось прекратить присаживанием/укладыванием, могут поддерживать синкопальный механизм.','']},
  {title:'Ловушки',items:['Не ставь эпилепсию по наличию подёргиваний без контекста.','Не пропускай кардиальную причину у пациента с неврологически выглядящим эпизодом.','Не назначай ЭЭГ как универсальный скрининг любого обморока.']}
 ],sources:[]},
 {id:'cluster-headache',title:'Кластерная головная боль и тригеминальные автономные цефалгии',category:'Заболевания',tags:['кластерная головная боль','цефалгия','тригеминальные автономные цефалгии','слезотечение','ринорея','автономные симптомы'],updated:'Клинический обзор · РФ',summary:'Очень сильная строго односторонняя орбитальная/височная боль с ипсилатеральными автономными симптомами и двигательным беспокойством требует распознавания характерного паттерна.',sections:[
  {title:'Характерный фенотип',items:['Боль обычно очень интенсивная, односторонняя, орбитальная/надорбитальная/височная; приступы стереотипны и имеют ограниченную длительность.','Сопутствующие признаки на стороне боли: слезотечение, покраснение глаза, заложенность носа/ринорея, отёк века, потливость лица, миоз или птоз.','Для кластерного паттерна характерны серии приступов (пучки/периоды) и выраженное беспокойство или невозможность спокойно лежать во время приступа.','Уточни суточную периодичность, длительность серии, ремиссии, ночные пробуждения, алкоголь как триггер во время активного периода и частоту приступов.']},
  {title:'Дифференциальная диагностика и обследование',items:['Сопоставляй с мигренью, пароксизмальной гемикранией, короткие односторонние невралгиформные приступы с краниальными вегетативными проявлениями, гемикранией континуа и вторичной орбитальной/сосудистой патологией.','','Внезапная максимальная боль за минуты, новый неврологический дефицит, лихорадка, когнитивное изменение или болезненный красный глаз требуют оценки вторичной причины.']},
  {title:'',items:['','','','']},
  {title:'Ловушки',items:['Не путай кластерную боль с мигренью только по интенсивности.','Не пропускай красные флаги вторичной головной боли.','Не начинай верапамил без контроля ЭКГ и профильного плана.']}
 ],sources:[]},
 {id:'myasthenia',title:'Миастения: флюктуирующая слабость и миастенический криз',category:'Заболевания',tags:['миастения','нервно-мышечная передача','птоз','диплопия','утомляемость','дисфагия','миастенический криз'],updated:'Клинический обзор · РФ',summary:'Колеблющаяся утомляемая слабость, особенно глазная и бульбарная, должна навести на мысль о нарушении нервно-мышечной передачи. Дыхательное или глотательное ухудшение — экстренный риск.',sections:[
  {title:'Клинический фенотип',items:['Типичны флюктуирующие слабость и утомляемость, усиливающиеся при повторной нагрузке и к концу дня, с частичным улучшением после отдыха.','Часто вовлекаются мышцы глаз и век: птоз, диплопия, изменчивое ограничение движений глаз.','Бульбарные проявления: утомляемость при жевании, дисфагия, поперхивание, назальная/тихая речь, дизартрия и слабость мимики.','Возможны слабость шеи и конечностей, трудности при подъёме по лестнице, вставании, удержании головы и выполнении повторных движений.']},
  {title:'Осмотр и диагностическая логика',items:['Оцени вариабельность симптомов во времени, провоцирование повторной нагрузкой и восстановление после отдыха.','Проверь глазодвигательные функции, птоз, закрытие глаз, мимику, речь, глотание, силу шеи и конечностей; ищи сохранность чувствительности и отсутствие типичного пирамидного паттерна.','Диагностический путь может включать антитела к компонентам нервно-мышечного синапса, нейрофизиологические исследования и визуализацию средостения по решению профильного специалиста.','Нормальный результат одного теста не всегда исключает заболевание: чувствительность зависит от фенотипа и метода, особенно при изолированной глазной форме.']},
  {title:'Признаки кризиса и срочность',items:['Нарастающая одышка, слабый кашель, невозможность удерживать голову, быстро прогрессирующая дисфагия, поперхивание слюной или изменение голоса могут указывать на угрожающее бульбарное/дыхательное ухудшение.','При тяжёлых нарушениях дыхания или глотания нужна немедленная экстренная оценка и мониторинг дыхательной функции; не ориентируйся только на субъективное ощущение нехватки воздуха.','Инфекция, операция, стресс и некоторые лекарства могут ухудшать состояние; уточняй недавние изменения терапии и возможные триггеры.']},
  {title:'Ловушки',items:['Не называй общую усталость миастенией без объективного паттерна утомляемой слабости.','Не исключай миастению при отсутствии выраженного птоза: возможны бульбарные и генерализованные варианты.','Не оставляй пациента с нарастающей дисфагией или дыхательными симптомами на плановое наблюдение.']}
 ],sources:[]},
 {id:'optic-neuritis',title:'Оптический неврит и острое снижение зрения',category:'Синдромы',tags:['оптический неврит','неврит зрительного нерва','снижение зрения','дисхроматопсия','заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину','заболевание спектра оптиконейромиелита','рассеянный склероз'],updated:'Клинический обзор · РФ',summary:'Подострое монокулярное снижение зрения с болью при движении глаза может соответствовать оптическому невриту, но внезапная потеря зрения требует исключения сосудистых и офтальмологических причин.',sections:[
  {title:'Клинические ориентиры',items:['Частый паттерн — снижение зрения на один глаз, развивающееся в течение часов или дней, с ретробульбарной болью или болью при движении глаза.','Уточни снижение цветоощущения/яркости, дефект поля зрения, метаморфопсии, фотопсии и динамику восстановления.','Оцени остроту зрения каждого глаза отдельно, цветоощущение, зрачковые реакции и относительный афферентный зрачковый дефект при асимметричном поражении.','Осмотр диска зрительного нерва может быть нормальным при ретробульбарном неврите; нормальная офтальмоскопия не исключает поражение зрительного нерва.']},
  {title:'Дифференциальная диагностика',items:['Различай воспалительный неврит, переднюю ишемическую оптическую нейропатию, компрессионное/инфильтративное поражение, ретинальную патологию, инфекционные и системные воспалительные причины.','Двустороннее, тяжёлое, рецидивирующее или атипичное течение, выраженный отёк диска либо продольное поражение зрительного нерва требует рассмотрения заболевание спектра оптиконейромиелита, заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину и других причин.','При внезапной безболезненной потере зрения особенно важно исключить сосудистое поражение сетчатки/зрительного нерва; это требует срочной офтальмологической оценки.']},
  {title:'Исследования и направление',items:['При подозрении на оптический неврит требуется срочная совместная оценка офтальмолога и невролога/нейроофтальмолога в зависимости от доступности.','МРТ головного мозга и орбит с соответствующими последовательностями, а также лабораторные тесты (включая антитела к аквапорину-4 и миелин-олигодендроцитарному гликопротеину при показаниях) выбираются по фенотипу и специалистом.','Не приравнивай оптический неврит к рассеянному склерозу: это синдром с несколькими возможными этиологиями.']},
  {title:'Ловушки',items:['Не успокаивайся нормальным видом диска зрительного нерва при типичной ретробульбарной клинике.','Не пропускай ишемическую или компрессионную причину острой потери зрения.','Не ставь диагноз РС только по эпизоду оптического неврита.']}
 ],sources:[]},
 {id:'cervical-myelopathy',title:'Шейная миелопатия и компрессия спинного мозга',category:'Неотложные состояния',tags:['шейная миелопатия','компрессия спинного мозга','гиперрефлексия','неуклюжесть кистей','нарушение походки','патологические рефлексы'],updated:'Клинический обзор · РФ',summary:'Сочетание неловкости кистей, нарушения походки и пирамидных знаков должно заставить искать поражение спинного мозга, даже если пациент жалуется на боль в шее или её вообще нет.',sections:[
  {title:'Клинические проявления',items:['Постепенное ухудшение тонкой моторики кистей: трудности с пуговицами, письмом, мелкими предметами, частое выпадение вещей.','Нарушение походки, скованность ног, неустойчивость, спастичность и ощущение «тяжёлых» конечностей.','Гиперрефлексия, патологические стопные знаки, клонусы, повышение тонуса и признаки поражения длинных проводящих путей ниже уровня компрессии.','Возможны парестезии, онемение, боль в шее/плечах и позднее — нарушения мочеиспускания/дефекации.']},
  {title:'Осмотр и локализация',items:['Оцени силу и ловкость кистей, быстрые чередующиеся движения, тонус, сухожильные рефлексы рук и ног, патологические рефлексы и походку.','Ищи сочетание признаков верхнего мотонейрона в ногах с сегментарными/корешковыми признаками в руках.','Уточни прогрессирование, падения, травмы, онкологический анамнез, инфекционные симптомы и тазовые нарушения.','Отличай шейную миелопатию от изолированной радикулопатии: при миелопатии ожидаются признаки поражения спинного мозга, часто ниже уровня поражения.']},
  {title:'Срочность',items:['','Новые нарушения функции мочевого пузыря/кишечника, быстро нарастающая слабость или значимое ухудшение ходьбы требуют немедленной оценки.','При подозрении на компрессию спинного мозга необходима срочная профильная оценка и МРТ по локальному маршруту; не задерживай её длительным эмпирическим лечением «остеохондроза».']},
  {title:'Ловушки',items:['Не требуй обязательного наличия боли в шее для подозрения на миелопатию.','Не списывай гиперрефлексию и нарушение походки на возраст без топической оценки.','Не трактуй изменения на рентгене как достаточное исследование спинного мозга.']}
 ],sources:[]}


,
 {id:'meningitis',title:'Менингит и энцефалит: острые инфекционные поражения ЦНС',category:'Неотложные состояния',tags:['менингит','энцефалит','лихорадка','головная боль','ригидность затылка','петехии','нарушение сознания'],updated:'Клинический обзор · РФ',summary:'Инфекции ЦНС могут быстро прогрессировать и не всегда дают полный классический набор симптомов. При клиническом подозрении нужна экстренная госпитальная оценка.',sections:[
  {title:'Когда подозревать',items:['','Отсутствие одного или нескольких элементов не исключает менингит: клиническая оценка может поддерживать подозрение и без полной комбинации.','Дополнительные признаки: светобоязнь, рвота, судороги, очаговый дефицит, необычное поведение, вялость и системное ухудшение.','При менингококковой инфекции настораживают небледнеющая петехиальная/пурпурная сыпь, особенно быстро распространяющаяся; отсутствие сыпи не исключает заболевание.']},
  {title:'Первичная оценка',items:['Оцени проходимость дыхательных путей, дыхание, кровообращение, гемодинамику, уровень сознания, неврологический статус, судороги, признаки сепсиса и внутричерепной гипертензии.','Уточни скорость развития, лихорадку/антипиретики, вакцинацию, иммунодефицит, асплению, недавние инфекции, контакт с заболевшими, ликворею и кохлеарный имплант.','У пациента с нарушением сознания или коммуникации обязательно получи сведения у родственников/очевидцев о недавнем изменении поведения и функции.','']},
  {title:'Дифференциальный ряд и исследования',items:['Рассмотри вирусный энцефалит, абсцесс, сепсис, субарахноидальное кровоизлияние, аутоиммунный энцефалит, токсико-метаболические причины и постиктальное состояние.','Решение о КТ/МРТ до люмбальной пункции зависит от клинических противопоказаний и признаков риска; сама пункция не должна создавать опасную задержку терапии.','Люмбальная пункция, посевы/ПЦР крови и ликвора, визуализация и ЭЭГ выбираются по клинической ситуации и локальному протоколу.','При энцефалитическом фенотипе с изменением поведения, сознания, судорогами или очаговыми симптомами оцени вероятность энцефалита, вызванного вирусом простого герпеса, и других причин; лечение организует стационарная команда.']},
  {title:'Ловушки',items:['Не жди полного классического менингеального синдрома, особенно у пожилых, иммунокомпрометированных и пациентов с нарушением коммуникации.','Не исключай менингококковую болезнь при отсутствии сыпи.','Не задерживай экстренную маршрутизацию ради завершения амбулаторного обследования.']}
 ],sources:[]},
 {id:'polyneuropathy',title:'Дистальная симметричная полинейропатия',category:'Заболевания',tags:['полинейропатия','периферическая нейропатия','дистальная слабость','онемение стоп','ахилловы рефлексы','B12','диабет'],updated:'Клинический обзор · РФ',summary:'Длина-зависимое симметричное поражение начинается обычно со стоп. Важны темп, модальности, рефлексы, автономные проявления и поиск потенциально обратимой причины.',sections:[
  {title:'Фенотип и распределение',items:['Уточни начало, скорость прогрессирования, симметрию, последовательность вовлечения стоп и кистей, боль, жжение, онемение, слабость и нарушение равновесия.','Проверь дистальную силу, атрофии, тонус, ахилловы и коленные рефлексы, вибрацию, проприоцепцию, болевую и температурную чувствительность.','Длина-зависимый паттерн обычно начинается дистально в ногах; раннее вовлечение кистей, выраженная асимметрия или проксимальная слабость требуют расширения дифференциального ряда.','Уточни ортостатические симптомы, потоотделение, кишечную/мочевую дисфункцию, эректильные нарушения и другие признаки автономного поражения.']},
  {title:'Причины и первичная оценка',items:['Частые потенциальные причины включают диабет/нарушение гликемии, алкоголь, дефицит B12, заболевания щитовидной железы и почек, лекарства/токсины, парапротеинемии и наследственные состояния.','','Дополнительные анализы, включая общий анализ крови, печёночные показатели, электрофорез белков/иммунофиксацию и другие тесты, выбираются по клиническому паттерну и локальным рекомендациям.','Собери полный лекарственный и токсикологический анамнез, включая химиотерапию, добавки и возможный избыток витамина B6.']},
  {title:'Когда ускорять обследование',items:['Быстрое прогрессирование, выраженная асимметрия, моторное преобладание, проксимальная слабость, поражение черепных нервов, дыхательные/бульбарные симптомы или автономная нестабильность требуют срочной профильной оценки.','Сочетание чувствительного дефицита с оживлёнными рефлексами, патологическими стопными знаками или нарушением походки заставляет искать поражение головного/спинного мозга.','ЭНМГ помогает охарактеризовать аксональный/демиелинизирующий паттерн и моторное/сенсорное вовлечение, но не заменяет клиническую локализацию и лабораторный поиск причины.']},
  {title:'Ловушки',items:['Не ставь диагноз «диабетическая нейропатия» только на основании диабета: оцени альтернативные причины и нетипичный паттерн.','Не назначай широкую лабораторную панель без клинической гипотезы.','Не пропускай центральные признаки у пациента с жалобами на онемение стоп.']}
 ],sources:[]},
 {id:'myelitis',title:'Острый миелит и синдром поражения спинного мозга',category:'Неотложные состояния',tags:['миелит','поперечный миелит','сенсорный уровень','парапарез','тазовые нарушения','заболевание спектра оптиконейромиелита','заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину'],updated:'Клинический обзор · РФ',summary:'Острое развитие слабости, чувствительного уровня и тазовых нарушений требует срочного исключения компрессии и воспалительного поражения спинного мозга.',sections:[
  {title:'Клинический синдром',items:['Уточни скорость появления слабости, онемения/дизестезий, боли в спине, чувствительного уровня и нарушений мочеиспускания/дефекации.','Проверь силу, тонус, сухожильные рефлексы, патологические стопные знаки, чувствительность по дерматомам и наличие чёткой границы чувствительного уровня.','Оцени дыхательную функцию при высоком шейном поражении, бульбарные симптомы и способность самостоятельно ходить.','Боль в спине, корешковая боль и тазовые симптомы могут указывать на компрессию; воспалительная миелопатия не должна становиться диагнозом до исключения структурной причины.']},
  {title:'Неотложные развилки',items:['При остром/подостром спинальном синдроме срочно исключай эпидуральную компрессию, опухоль, абсцесс, гематому, травму и сосудистое поражение.','МРТ спинного мозга с соответствующими отделами и контрастированием выбирается по клинической ситуации; при подозрении на компрессию исследование не откладывают.','Лихорадка, иммунодефицит, онкологический анамнез, недавняя инфекция/процедура, антикоагулянты и быстрое нарастание дефицита повышают срочность.']},
  {title:'Воспалительные причины',items:['При воспалительном миелите рассматривай РС, заболевание спектра оптиконейромиелита (антитела к аквапорину-4), заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину, системные аутоиммунные заболевания, инфекции и паранеопластические процессы.','При подозрении на заболевание спектра оптиконейромиелита учитывай сочетание миелита с оптическим невритом, стволовыми/диэнцефальными симптомами; эпизоды могут быть разнесены во времени.','Диагностический план может включать МРТ головного и спинного мозга, ликвор, антитела к аквапорину-4 и миелин-олигодендроцитарному гликопротеину и исследования на инфекционные/аутоиммунные причины; выбор и интерпретация — задача профильной команды.']},
  {title:'Ловушки',items:['Не объясняй острый парапарез только дегенеративными изменениями без оценки спинного мозга.','Не пропускай компрессию до пункции или назначения иммунотерапии.','Не объединяй все воспалительные миелиты в диагноз РС: заболевание спектра оптиконейромиелита и заболевание, ассоциированное с антителами к миелин-олигодендроцитарному гликопротеину имеют отдельные критерии и тактику.']}
 ],sources:[]}


,
 {id:'diplopia',title:'Диплопия: монокулярное и бинокулярное двоение',category:'Симптомы',tags:['диплопия','двоение','глазодвигательные нервы','III нерв','IV нерв','VI нерв','ствол мозга','миастения'],updated:'Клинический обзор · РФ',summary:'Первый шаг — установить, исчезает ли двоение при закрытии любого одного глаза. Внезапная бинокулярная диплопия может быть проявлением опасного неврологического или сосудистого процесса.',sections:[
  {title:'Сначала классифицируй жалобу',items:['Монокулярная диплопия сохраняется, когда второй глаз закрыт; чаще связана с оптическими или офтальмологическими причинами, а не с нарушением согласованной работы глазодвигательной системы.','Бинокулярная диплопия исчезает при закрытии любого из глаз и указывает на нарушение взаимного положения глаз или их движений.','Уточни направление двоения, постоянство или эпизодичность, расстояние, на котором оно возникает, связь с усталостью и временем суток.','Отдельно выясни, есть ли птоз, боль, головная боль, снижение зрения, анизокория, слабость, дизартрия, дисфагия, атаксия или нарушение чувствительности.']},
  {title:'Опасные причины и срочность',items:['Внезапная бинокулярная диплопия с очаговыми симптомами, атаксией, дизартрией, головокружением или нарушением походки требует немедленной оценки на поражение ствола мозга и инсульт задней циркуляции.','Болезненная офтальмоплегия, выраженная головная боль, изменение сознания или другие новые неврологические признаки требуют срочной оценки внутричерепной и сосудистой патологии.','Птоз с расширенным или плохо реагирующим зрачком и нарушением движений глаза требует экстренного исключения компрессии III нерва, в том числе аневризматической причины.','Острая диплопия после травмы, при иммунодефиците, онкологическом анамнезе или системных симптомах требует расширенного поиска причины.']},
  {title:'Осмотр и топическая логика',items:['Оцени остроту зрения каждого глаза отдельно, зрачки и их реакцию, положение глаз в первичной позиции, птоз и объём движений во всех направлениях взора.','Определи, в каком направлении двоение усиливается; сопоставь ограничение движения с возможным поражением III, IV или VI нерва, нервно-мышечной передачи, орбиты или стволовых структур.','Проверь движения глаз при взгляде в стороны и вверх/вниз, конвергенцию, нистагм, саккады и плавное слежение; оцени остальные черепные нервы и координацию.','Флюктуирующая диплопия и птоз, усиливающиеся при нагрузке и уменьшающиеся после отдыха, заставляют рассматривать миастению; отсутствие зрачковых нарушений поддерживает, но не доказывает эту гипотезу.']},
  {title:'Дифференциальный ряд',items:['Монокулярная диплопия: нарушения рефракции, поверхности глаза, хрусталика и другие офтальмологические причины.','Бинокулярная диплопия: парез глазодвигательного нерва, декомпенсация фории/страбизма, поражение ствола мозга, миастения, тиреоидная орбитопатия, орбитальное воспаление или объёмный процесс.','Сочетание боли, проптоза, хемоза, лихорадки или ограничения движений глаза требует оценки орбитальной патологии и инфекционных причин.','Изолированная диплопия не должна автоматически трактоваться как микроангиопатический парез нерва без оценки зрачков, боли, факторов риска и динамики.']},
  {title:'Ловушки и дальнейшая оценка',items:['Не называй любое субъективное «раздваивание» диплопией до проверки каждого глаза отдельно.','Не ограничивай осмотр глазодвигательными движениями: зрачки, веки, зрение и сопутствующие стволовые симптомы меняют срочность.','Не используй нормальную силу в конечностях как аргумент против небольшого стволового очага.','Выбор нейровизуализации, сосудистого исследования, лабораторных тестов и офтальмологической оценки определяется локализацией, временем начала и клинической срочностью.']}
 ],sources:[]},
 {id:'ptosis',title:'Птоз: остро возникшее и флюктуирующее опущение века',category:'Симптомы',tags:['птоз','опущение века','анизокория','синдром Горнера','III нерв','миастения'],updated:'Клинический обзор · РФ',summary:'Птоз — не диагноз, а признак. Важнейшие развилки: зрачки, движения глаза, боль, скорость появления и утомляемость симптома.',sections:[
  {title:'Фенотип и анамнез',items:['Уточни, когда появился птоз, внезапно или постепенно, постоянен ли он, меняется ли в течение дня и усиливается ли при длительном взгляде вверх.','Выясни, односторонний он или двусторонний, сопровождается ли диплопией, болью в голове/шее/глазу, изменением зрения или слабостью других мышц.','Спроси о травме, операциях, инъекциях ботулотоксина, контактных линзах, перенесённых заболеваниях и лекарствах.','Сравни фотографии пациента в динамике, если они доступны: давность и прогрессирование могут быть диагностически полезны.']},
  {title:'Красные флаги',items:['Острый птоз с анизокорией, особенно с более широким зрачком на стороне птоза и нарушением движений глаза, требует экстренного исключения компрессии III нерва.','Птоз и миоз с новой односторонней болью в голове или шее требуют срочной оценки синдрома Горнера и возможного поражения сонной артерии.','Птоз с диплопией, атаксией, дизартрией, слабостью, нарушением чувствительности или изменением сознания требует оценки центральной неврологической причины.','Бульбарные симптомы, одышка, слабый кашель или быстро нарастающая генерализованная слабость на фоне подозрения на миастению — потенциально жизнеугрожающий сценарий.']},
  {title:'Осмотр и локализация',items:['Оцени высоту верхнего века, симметрию глазных щелей, положение глаз, движения глаз и наличие диплопии.','Измерь и сравни зрачки при ярком и приглушённом освещении; оцени прямую и содружественную реакцию на свет.','Проверь движения глаза по направлениям, включая приведение, отведение, подъём и опускание; ищи сочетанный парез глазодвигательного нерва.','При подозрении на миастению оцени изменчивость птоза, утомляемость при длительном взгляде вверх, динамику после отдыха и другие глазные/бульбарные проявления.']},
  {title:'Основные диагностические направления',items:['Поражение III нерва: птоз может сочетаться с нарушением приведения, подъёма и опускания глаза; состояние зрачка и боль критически важны для срочной оценки.','Синдром Горнера: сочетание частичного птоза и миоза; при остром болевом начале необходимо исключать сосудистую причину.','Миастения: вариабельный, утомляемый птоз, нередко с диплопией; зрачки обычно не вовлечены. Диагноз подтверждается профильной оценкой, а не одной прикроватной пробой.','Механический, апоневротический и миогенный птоз рассматривают с учётом возраста, анамнеза, положения века и отсутствия неврологических сопутствующих признаков.']},
  {title:'Ловушки',items:['Не успокаивайся только потому, что птоз небольшой: значение имеют зрачок, боль и сопутствующая офтальмоплегия.','Не диагностируй миастению только по утомляемости века без оценки альтернатив и подтверждающих исследований.','Не считай синдром Горнера доброкачественным до оценки острого болевого начала и возможной диссекции.','Маршрут обследования должен соответствовать предполагаемой локализации и срочности; при красных флагах амбулаторное наблюдение не заменяет экстренную оценку.']}
 ],sources:[]},
 {id:'gait',title:'Нарушение походки и постуральной устойчивости',category:'Синдромы',tags:['походка','неустойчивость','атаксия','паркинсонизм','спастическая походка','степпаж','падения'],updated:'Клинический обзор · РФ',summary:'Описывай конкретный паттерн походки и условия, в которых он возникает. Жалоба на «шаткость» сама по себе не локализует поражение.',sections:[
  {title:'Сначала уточни временной профиль и контекст',items:['Внезапное нарушение походки, особенно с головокружением, диплопией, дизартрией, слабостью или чувствительными симптомами, требует немедленной оценки сосудистой причины.','Уточни начало, прогрессирование, эпизодичность, связь с нагрузкой, темнотой, закрытием глаз, поворотами, вставанием и приёмом лекарств.','Спроси о падениях, травмах, страхе падения, использовании опоры, боли, головокружении, обмороках и изменении повседневной активности.','Проверь лекарства и вещества, способные ухудшать равновесие: седативные препараты, алкоголь, некоторые противосудорожные и гипотензивные средства.']},
  {title:'Клинические паттерны',items:['Мозжечковая атактическая походка: расширенная база, вариабельная длина шага, отклонения в стороны и трудности с тандемной ходьбой; сопоставляй с дисметрией, дисдиадохокинезом и нистагмом.','Сенситивная атаксия: ухудшение устойчивости при снижении зрительного контроля, положительная проба Ромберга в соответствующем контексте, нарушение проприоцепции и вибрационной чувствительности.','Паркинсоническая походка: уменьшение размаха рук, мелкие шаги, затруднение начала движения, поворотов и эпизоды застывания; ищи брадикинезию и ригидность.','Спастическая походка: скованность, циркумдукция или приведение ног; оцени тонус, рефлексы, патологические стопные знаки и возможный уровень поражения.','Степпаж: высокий подъём ноги с последующим шлепком стопы, часто при слабости тыльных сгибателей; локализуй поражение по силе, чувствительности и рефлексам.','Анталгическая походка и ортопедические причины требуют оценки боли, объёма движений и опорно-двигательного аппарата, но не отменяют неврологический осмотр при нетипичных признаках.']},
  {title:'Осмотр',items:['Наблюдай вставание со стула, начало ходьбы, обычный шаг, поворот, остановку, ходьбу на носках и пятках, тандемную ходьбу и разворот.','Оцени ширину базы, длину и симметрию шага, скорость, высоту подъёма стопы, размах рук, положение туловища и способность менять направление.','Проверь силу проксимальных и дистальных мышц, тонус, сухожильные рефлексы, подошвенные ответы, проприоцепцию, вибрацию, координацию и движения глаз.','Измеряй ортостатическое давление и пульс, если симптомы связаны со вставанием; оцени зрение, обувь, боль и факторы среды.']},
  {title:'Когда нужна срочная оценка',items:['Острое начало с очаговым дефицитом, выраженной атаксией или невозможностью стоять/ходить требует исключения инсульта и другой острой центральной патологии.','Прогрессирующее нарушение походки с гиперрефлексией, патологическими стопными знаками, чувствительным уровнем или тазовыми симптомами заставляет искать миелопатию/компрессию спинного мозга.','Быстро нарастающая слабость, бульбарные или дыхательные симптомы требуют срочной оценки нейромышечного процесса.','Повторные падения, быстрое функциональное ухудшение, когнитивные изменения или новая асимметрия требуют ускоренного обследования даже без внезапного начала.']},
  {title:'Ловушки и исследования',items:['Не называй любую неустойчивость мозжечковой атаксией: сенсорные, вестибулярные, паркинсонические, пирамидные и лекарственные причины дают разные паттерны.','Проба Ромберга оценивает вклад зрительного контроля в поддержание позы и не является самостоятельным тестом на мозжечковое поражение.','Нейровизуализация, лабораторные исследования, ЭНМГ и оценка вестибулярной системы назначаются по локализации и темпу развития, а не по одному слову «шаткость».','Зафиксируй исходную функциональную способность и динамику: это помогает отличать прогрессирование от колебаний и оценивать эффект коррекции обратимых факторов.']}
 ],sources:[]},
 {id:'dysphagia',title:'Дисфагия и бульбарный синдром',category:'Синдромы',tags:['дисфагия','бульбарный синдром','дизартрия','аспирация','миастения','БАС','ствол мозга'],updated:'Клинический обзор · РФ',summary:'Нарушение глотания может быстро привести к аспирации и дыхательным осложнениям. Важны скорость начала, безопасность дыхательных путей и сочетание с другими бульбарными симптомами.',sections:[
  {title:'Как описать нарушение глотания',items:['Уточни, трудно ли начать глотание, возникает ли кашель или поперхивание во время еды, есть ли ощущение застревания пищи, регургитация или изменение голоса после глотка.','Раздели трудности с жидкой и твёрдой пищей, оцени длительность приёма пищи, потерю веса, обезвоживание, инфекции дыхательных путей и избегание определённых консистенций.','Спроси о носовом оттенке речи, дизартрии, слабости жевания, утомляемости, двоении, птозе и слабости шеи/конечностей.','Уточни внезапность симптомов, недавний инсульт, прогрессирование, лекарства, операции, опухоли головы/шеи и заболевания нервно-мышечной системы.']},
  {title:'Красные флаги и срочность',items:['Внезапная дисфагия с дизартрией, асимметрией лица, слабостью, атаксией или другими очаговыми признаками требует немедленной оценки инсульта.','Невозможность справляться со слюной, повторные эпизоды удушья, выраженная слабость кашля, одышка или быстрое ухудшение требуют экстренной оценки дыхательных путей и аспирационного риска.','Бульбарные симптомы на фоне подозрения на миастению могут предшествовать дыхательной декомпенсации; при нарастании симптомов нужна срочная стационарная оценка.','Лихорадка, гипоксия, тахипноэ или признаки аспирационной пневмонии требуют отдельной неотложной оценки.']},
  {title:'Неврологическая локализация',items:['Псевдобульбарный паттерн может сопровождаться спастической дизартрией, эмоциональной лабильностью и другими признаками двустороннего кортико-бульбарного поражения.','Бульбарное поражение ядер/нервов может сопровождаться атрофией и фасцикуляциями языка, слабостью мягкого нёба, дисфонией и снижением защитных рефлексов; оценивай контекст и не полагайся на один признак.','Нервно-мышечная передача: флюктуирующая утомляемость, носовая речь, жевательная слабость, птоз/диплопия и ухудшение к концу дня поддерживают гипотезу миастении.','Стволовой очаг может сочетать дисфагию с глазодвигательными, чувствительными, координаторными и двигательными нарушениями.']},
  {title:'Оценка и обследование',items:['Оцени голос, артикуляцию, движения языка и мягкого нёба, силу кашля, управление слюной и способность поддерживать дыхание.','Клиническая оценка глотания не всегда исключает скрытую аспирацию; при показаниях требуется инструментальная оценка специалистами по глотанию.','При подозрении на инсульт действуй по инсультному маршруту; до оценки безопасности глотания не следует считать пероральный приём безопасным.','При прогрессирующем бульбарном синдроме оцени дыхательную функцию, питание, массу тела, гидратацию и необходимость мультидисциплинарного ведения.']},
  {title:'Ловушки',items:['Не путай субъективное ощущение кома в горле с объективной дисфагией, но и не списывай жалобу без уточнения фаз и последствий глотания.','Не делай вывод о безопасности глотания только по отсутствию кашля: аспирация может быть малосимптомной.','Не задерживай оценку дыхания при сочетании дисфагии, слабого кашля и генерализованной слабости.','Не назначай единую схему обследования всем пациентам: срочность и тесты зависят от предполагаемого уровня поражения и клинического контекста.']}
 ],sources:[]}

];
function renderClinical(){
 return '<div class="page-heading"><div><div class="eyebrow">КЛИНИЧЕСКАЯ БАЗА ЗНАНИЙ</div><h1>Клинический справочник</h1><p class="lead">Развёрнутые клинические статьи: фенотип синдрома, топическая логика, дифференциальный ряд, обследование, срочность и первоисточники.</p></div><span class="date-chip">31 клиническая статья · локальный поиск</span></div>'+
 '<section class="clinical-notice"><strong>'+icon('info',16)+' Российский контекст и границы справочника</strong><p>Материалы — редакционные обзоры для навигации по неврологической оценке, а не дословное изложение клинических рекомендаций и не система поддержки принятия решений. В справочнике используются только российские документы: клинические рекомендации, утверждённые Минздравом России, и официальные российские нормативные источники. Зарубежные руководства, сайты и клинические протоколы исключены. Если для конкретной темы отдельная российская клиническая рекомендация не подтверждена, это прямо указано; иностранная рекомендация не подставляется вместо неё. Перед применением сверяй действующую редакцию документа, возрастную группу и локальные порядки оказания медицинской помощи.</p></section>'+
 '<section class="card card-pad clinical-search-card"><label for="clinical-query" class="icd-search-label">Найти симптом, синдром или термин</label><div class="icd-search-row"><span class="icd-search-icon">'+icon('search',20)+'</span><input id="clinical-query" type="search" autocomplete="off" placeholder="Например: головокружение, парез, онемение…"><button id="clinical-clear" class="button button-outline" type="button">Очистить</button></div><div class="clinical-filter-row" id="clinical-filters"><button type="button" class="clinical-filter active" data-clinical-filter="Все">Все материалы</button><button type="button" class="clinical-filter" data-clinical-filter="Симптомы">Симптомы</button><button type="button" class="clinical-filter" data-clinical-filter="Синдромы">Синдромы</button><button type="button" class="clinical-filter" data-clinical-filter="Заболевания">Заболевания</button><button type="button" class="clinical-filter" data-clinical-filter="Неотложные состояния">Неотложные состояния</button></div><div class="clinical-results-meta" id="clinical-meta" role="status" aria-live="polite"></div><div class="clinical-results" id="clinical-results"></div></section>'+
 '<section class="clinical-method"><div class="eyebrow">КАК УСТРОЕНЫ МАТЕРИАЛЫ</div><div class="clinical-method-grid"><div><strong>01 · Срочность</strong><span>Признаки, которые нельзя пропустить</span></div><div><strong>02 · Оценка</strong><span>Что уточнить и проверить при осмотре</span></div><div><strong>03 · Логика</strong><span>Дифференциальные ориентиры и ловушки</span></div><div><strong>04 · Источники</strong><span>Ссылки на рекомендации и дату редакции</span></div></div></section>';
}
function bindClinical(){
 const query=document.getElementById('clinical-query'),results=document.getElementById('clinical-results'),meta=document.getElementById('clinical-meta'),filters=document.getElementById('clinical-filters');
 let category='Все';
 const openArticles=new Set(new URLSearchParams(location.search).getAll('article').filter(id=>CLINICAL_LIBRARY.some(item=>item.id===id)));
 const russianGuidelines={
  headache:[{label:'КР Минздрава России «Мигрень», взрослые · 2024 · ID 295_4 · действует',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'},{label:'КР Минздрава России «Головная боль напряжения», дети · 2024 · ID 810_1',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  seizure:[{label:'КР Минздрава России «Эпилепсия и эпилептический статус у взрослых и детей» · 2022 · ID 741 · актуальный статус требует перепроверки',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  status:[{label:'КР Минздрава России «Эпилепсия и эпилептический статус у взрослых и детей» · 2022 · ID 741 · актуальный статус требует перепроверки',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  polyneuropathy:[{label:'КР Минздрава России «Сахарный диабет 2 типа у взрослых» · 2022 · ID 290_2 · только раздел о диабетической нейропатии; не общая полинейропатия',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  stroke:[{label:'КР Минздрава России «Ишемический инсульт и транзиторная ишемическая атака» · 2024 · ID 814_1 · действует',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  tia:[{label:'КР Минздрава России «Ишемический инсульт и транзиторная ишемическая атака» · 2024 · ID 814_1 · действует',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  myasthenia:[{label:'КР Минздрава России «Миастения» · 2025 · ID 165_2 · действует',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  delirium:[{label:'КР Минздрава России «Делирий, не обусловленный алкоголем и другими психоактивными веществами, у лиц пожилого и старческого возраста» · 2026 · ID 742_2 · действует',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}],
  dementia:[{label:'КР Минздрава России «Когнитивные расстройства у лиц пожилого и старческого возраста» · 2024 · ID 617_5',url:'https://minzdrav.gov.ru/smartphone_apps_rubrikator_kr.'}]
 };
 const articleMarkup=item=>{
  const sections=item.sections.map(section=>({...section,items:section.items.filter(Boolean)})).filter(section=>section.items.length);
  const sources=russianGuidelines[item.id]||[];
  return '<div class="clinical-article-panel is-open" data-clinical-panel="'+item.id+'"><div class="clinical-article-panel-inner"><article class="clinical-article" id="clinical-article-'+item.id+'"><div class="clinical-article-head"><div><span class="clinical-category">'+esc(item.category)+'</span><h2>'+esc(item.title)+'</h2><p>'+esc(item.summary)+'</p></div><button type="button" class="clinical-collapse" data-clinical-close="'+item.id+'" aria-label="Свернуть статью" title="Свернуть статью">'+icon('close',19)+'</button></div><nav class="clinical-article-toc" aria-label="Содержание статьи"><strong>Содержание</strong>'+sections.map((section,i)=>'<button type="button" class="clinical-toc-link" data-clinical-section-target="clinical-section-'+item.id+'-'+i+'">'+String(i+1).padStart(2,'0')+' · '+esc(section.title)+'</button>').join('')+'</nav>'+sections.map((section,i)=>'<section class="clinical-article-section" id="clinical-section-'+item.id+'-'+i+'"><h3><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(section.title)+'</h3><ul>'+section.items.map(line=>'<li>'+esc(line)+'</li>').join('')+'</ul></section>').join('')+'<section class="clinical-sources"><h3>Российские клинические рекомендации</h3>'+(sources.length?sources.map(source=>'<a href="'+esc(source.url)+'" target="_blank" rel="noopener noreferrer">'+esc(source.label)+' '+icon('external',13)+'</a>').join('')+'<p class="clinical-source-note">Ссылка ведёт на официальную страницу Минздрава с информацией о Рубрикаторе КР. Сам рубрикатор на момент проверки сообщал о технических работах; для поиска документа используй его название или ID, указанный выше.</p>':'<p>Отдельная российская клиническая рекомендация, непосредственно соответствующая этой теме, пока не подтверждена. Зарубежные источники не используются и не подставляются вместо российского документа.</p>')+'</section></article></div></div>';
 };
 const updateUrl=()=>{const url=new URL(location.href);url.searchParams.delete('article');[...openArticles].forEach(id=>url.searchParams.append('article',id));history.replaceState(null,'',url.pathname+url.search+url.hash);};
 const normalizeSearch=value=>String(value??'').normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
 const render=()=>{
  const q=normalizeSearch(query.value),tokens=q.split(' ').filter(Boolean);
  const matches=CLINICAL_LIBRARY.filter(item=>{
   if(category!=='Все'&&item.category!==category)return false;
   if(!tokens.length)return true;
   const corpus=normalizeSearch([item.title,item.summary,item.category,...item.tags,...item.sections.flatMap(section=>[section.title,...section.items])].join(' '));
   const words=corpus.split(' ');
   return tokens.every(token=>{const stem=token.length>5?token.slice(0,-2):token;return corpus.includes(token)||words.some(word=>word.startsWith(stem)||(token.length>=5&&word.startsWith(token.slice(0,-1))));});
  }).sort((a,b)=>{
   const rank=item=>{const title=normalizeSearch(item.title);if(title===q)return 0;if(title.startsWith(q))return 1;if(item.tags.some(tag=>normalizeSearch(tag).startsWith(q)))return 2;return 3;};
   return rank(a)-rank(b);
  });
  meta.textContent='Найдено материалов: '+matches.length+' из '+CLINICAL_LIBRARY.length+(openArticles.size?' · открыто статей: '+openArticles.size:'');
  const openMarkup=[...openArticles].map(id=>CLINICAL_LIBRARY.find(item=>item.id===id)).filter(Boolean).map(articleMarkup).join('');
  const cards=matches.map(item=>'<div class="clinical-result-wrap"><button type="button" class="clinical-result '+(openArticles.has(item.id)?'selected':'')+'" data-clinical-open="'+item.id+'" aria-expanded="'+openArticles.has(item.id)+'" aria-controls="clinical-article-'+item.id+'"><span class="clinical-result-top"><span class="clinical-category">'+esc(item.category)+'</span><span class="clinical-updated">'+esc(item.updated)+'</span></span><strong>'+esc(item.title)+'</strong><span>'+esc(item.summary)+'</span><span class="clinical-tags">'+item.tags.map(tag=>'<i>'+esc(tag)+'</i>').join('')+'</span><span class="clinical-open-label">'+(openArticles.has(item.id)?'Статья открыта':'Открыть материал '+icon('arrow',13))+'</span></button></div>').join('');
  const emptyState='<div class="icd-empty"><strong>Ничего не найдено</strong><span>Попробуй другой термин или переключи категорию.</span></div>';
  results.innerHTML='<div class="clinical-layout'+(openMarkup?' has-open-articles':'')+'"><div class="clinical-results-list">'+(cards||emptyState)+'</div>'+(openMarkup?'<aside class="clinical-open-articles" aria-label="Открытые статьи">'+openMarkup+'</aside>':'')+'</div>';
  results.querySelectorAll('[data-clinical-open]').forEach(button=>button.addEventListener('click',()=>{
   const id=button.dataset.clinicalOpen;
   if(openArticles.has(id))openArticles.delete(id);else openArticles.add(id);
   updateUrl();render();
   if(openArticles.has(id)&&window.matchMedia('(max-width: 800px)').matches)results.querySelector('[data-clinical-panel="'+id+'"]')?.scrollIntoView({behavior:'smooth',block:'nearest'});
  }));
  results.querySelectorAll('[data-clinical-close]').forEach(button=>button.addEventListener('click',()=>{
   openArticles.delete(button.dataset.clinicalClose);updateUrl();render();
  }));
  results.querySelectorAll('[data-clinical-section-target]').forEach(button=>button.addEventListener('click',()=>{
   const section=document.getElementById(button.dataset.clinicalSectionTarget);
   if(section){section.scrollIntoView({behavior:'smooth',block:'start'});section.setAttribute('tabindex','-1');section.focus({preventScroll:true});}
  }));
 };
 query.addEventListener('input',render);
 document.getElementById('clinical-clear').addEventListener('click',()=>{query.value='';render();query.focus();});
 filters.querySelectorAll('[data-clinical-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.clinicalFilter;filters.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===button));render();}));
 render();
}
const PAGES={overview:{title:'Главная',render:renderOverview},icd:{title:'МКБ-10',render:renderICD},clinical:{title:'Клинический справочник',render:renderClinical}};
function render(){
  const route=routeName(),page=PAGES[route];
  setActiveNav(route);
  breadcrumb.textContent=page.title;
  app.innerHTML=page.render();
  if(route==='icd')bindICD();
  if(route==='clinical')bindClinical();
  closeSidebar();
  document.title=page.title+' — NeuroDesk';
}
function navigate(route){location.hash=route;}
document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-route]');
  if(nav){event.preventDefault();navigate(nav.dataset.route);}
});
window.addEventListener('hashchange',()=>{if(!location.pathname.endsWith('/clinical.html'))render();});
function closeSidebar(){sidebar.classList.remove('open');document.body.classList.remove('sidebar-open');document.getElementById('mobile-menu').setAttribute('aria-expanded','false');}
function toggleSidebar(){const open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);document.body.classList.toggle('sidebar-open',open);document.getElementById('mobile-menu').setAttribute('aria-expanded',String(open));}
document.getElementById('mobile-menu').addEventListener('click',toggleSidebar);
document.getElementById('sidebar-close')?.addEventListener('click',closeSidebar);
document.addEventListener('click',event=>{if(document.body.classList.contains('sidebar-open')&&!sidebar.contains(event.target)&&!event.target.closest('#mobile-menu'))closeSidebar();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSidebar();});
document.querySelectorAll('[data-icon]').forEach(node=>node.innerHTML=icon(node.dataset.icon));
try{render();}catch(error){console.error('NeuroDesk initialization failed:',error);app.innerHTML='<section class="startup-fallback"><h1>Не удалось загрузить раздел</h1><p>Основные страницы доступны по навигации. Обнови страницу; если ошибка повторяется, проверь подключение к файлам сайта.</p><a href="./index.html#overview">Вернуться на главную</a></section>';}
